	template<typename TControl, typename... TArgs>
	std::unique_ptr<TControl> MakeTestControl(TArgs&&... args)
	{
		auto normalizeGeometry = []<typename TValue>(TValue&& value)
			-> decltype(auto)
		{
			using Value = std::remove_cvref_t<TValue>;
			if constexpr (std::is_integral_v<Value>
				&& !std::is_same_v<Value, bool>)
				return static_cast<float>(value);
			else
				return std::forward<TValue>(value);
		};
		auto control = std::make_unique<TControl>();
		ConfigureTestControl(
			*control, normalizeGeometry(std::forward<TArgs>(args))...);
		return control;
	}

	template<typename TControl, typename... TArgs>
	TControl* AddTestVisual(Control& owner, TArgs&&... args)
	{
		return static_cast<TControl*>(owner.AddOwned(
			MakeTestControl<TControl>(std::forward<TArgs>(args)...)));
	}

	template<typename TControl, typename... TArgs>
	TControl* AddTestItem(ItemsControl& owner, TArgs&&... args)
	{
		return static_cast<TControl*>(owner.AddItemControl(
			MakeTestControl<TControl>(std::forward<TArgs>(args)...)));
	}

	ComboBoxItem* AddTestComboBoxItem(
		ComboBox& owner, std::wstring text)
	{
		return owner.AddItem(MakeTestControl<ComboBoxItem>(std::move(text)));
	}

	void SetTestComboBoxItems(
		ComboBox& owner, std::vector<std::wstring> values)
	{
		owner.ClearItems();
		for (auto& value : values)
			(void)AddTestComboBoxItem(owner, std::move(value));
	}

	std::wstring TestComboBoxItemText(
		const ComboBox& owner, size_t index)
	{
		const auto source = owner.GetItemsSource();
		if (source)
		{
			if (index >= source.Get()->Count()) return {};
			BindingSourceReference item;
			if (!source.Get()->TryGetItem(index, item) || !item) return {};
			return GetBindingRecordText(item, owner.GetDisplayMemberPath());
		}
		auto* item = owner.GetItem(static_cast<int>(index));
		return item ? item->GetContent().ToString() : std::wstring{};
	}

	std::vector<std::wstring> TestComboBoxItems(const ComboBox& owner)
	{
		std::vector<std::wstring> result;
		result.reserve(owner.ItemCount());
		for (size_t index = 0; index < owner.ItemCount(); ++index)
			result.push_back(TestComboBoxItemText(owner, index));
		return result;
	}

