    class ContextLayoutProbe final : public LayoutEngine
    {
    public:
        bool ReceivedWindowRoot = false;
        int ReceivedChildCount = 0;
        Control* ReceivedOwner = nullptr;

        cui::core::Size Measure(
            LayoutContext& context,
            const cui::core::Constraints& available) override
        {
            ReceivedWindowRoot = context.IsWindowRoot();
            ReceivedChildCount = context.ChildCount();
            ReceivedOwner = context.Owner();
            return available.maximum;
        }

        void Arrange(LayoutContext&, cui::core::Rect) override {}
    };

    class FractionalLayoutProbe final : public LayoutEngine
    {
    public:
        cui::core::Constraints ReceivedConstraints{};

        cui::core::Size Measure(
            LayoutContext&,
            const cui::core::Constraints& available) override
        {
            ReceivedConstraints = available;
            return { 17.625f, 9.375f };
        }

        void Arrange(LayoutContext&, cui::core::Rect) override {}
    };

	class IndexedVirtualProbe final : public Control
	{
	public:
		int IndexedCountQueries = 0;
		int IndexedChildQueries = 0;
		int IndexedSiblingQueries = 0;
		int DirectHitQueries = 0;
		std::array<uint32_t, 3> Ids{
			AllocateAccessibilityVirtualId(),
			AllocateAccessibilityVirtualId(),
			AllocateAccessibilityVirtualId() };

		IndexedVirtualProbe()
		{
			Canvas::SetLeft(*this, 530.0f);
			Canvas::SetTop(*this, 385.0f);
			Width = 180.0f;
			Height = 90.0f;
			Arrange({ 530.0f, 385.0f, 180.0f, 90.0f });
		}

		UIClass Type() override { return UIClass::UI_CUSTOM; }
		bool TryGetAccessibilityVirtualNode(
			uint32_t id, AccessibilityVirtualNode& result)
		{
			const auto position = std::find(Ids.begin(), Ids.end(), id);
			if (position == Ids.end()) return false;
			const int index = static_cast<int>(position - Ids.begin());
			result = {};
			result.Id = id;
			result.ControlType = AutomationControlType::ListItem;
			result.Name = L"Fast " + std::to_wstring(index);
			result.AutomationId = L"fast-node-" + std::to_wstring(index);
			result.BoundsDip = D2D1::RectF(
				0.0f, index * 30.0f, 180.0f, (index + 1) * 30.0f);
			result.Visible = true;
			result.Enabled = true;
			result.Row = index;
			return true;
		}
		size_t GetAccessibilityVirtualChildCount(uint32_t parentId)
		{
			++IndexedCountQueries;
			return parentId == 0 ? Ids.size() : 0;
		}
		bool TryGetAccessibilityVirtualChildAt(
			uint32_t parentId, size_t index, uint32_t& result)
		{
			++IndexedChildQueries;
			result = 0;
			if (parentId != 0 || index >= Ids.size()) return false;
			result = Ids[index];
			return true;
		}
		bool TryGetAccessibilityVirtualSibling(
			uint32_t parentId, uint32_t id, bool next, uint32_t& result)
		{
			++IndexedSiblingQueries;
			result = 0;
			if (parentId != 0) return false;
			const auto position = std::find(Ids.begin(), Ids.end(), id);
			if (position == Ids.end()) return false;
			const ptrdiff_t index = position - Ids.begin();
			const ptrdiff_t sibling = next ? index + 1 : index - 1;
			if (sibling < 0 || sibling >= static_cast<ptrdiff_t>(Ids.size()))
				return false;
			result = Ids[static_cast<size_t>(sibling)];
			return true;
		}
		bool TryHitTestAccessibilityVirtualNode(
			float localX, float localY, uint32_t& result)
		{
			++DirectHitQueries;
			result = 0;
			if (localX < 0.0f || localX >= 180.0f
				|| localY < 0.0f || localY >= 90.0f) return false;
			result = Ids[static_cast<size_t>(localY / 30.0f)];
			return true;
		}

	private:
		class Peer final : public AutomationPeer
		{
		public:
			explicit Peer(IndexedVirtualProbe& owner) :
				AutomationPeer(owner, AutomationControlType::List,
					L"IndexedVirtualProbe"),
				_owner(owner)
			{
			}

			bool SupportsVirtualizedChildren() const noexcept override
			{
				return true;
			}
			bool TryGetAccessibilityVirtualNode(
				uint32_t id, AccessibilityVirtualNode& result) override
			{
				return _owner.TryGetAccessibilityVirtualNode(id, result);
			}
			size_t GetAccessibilityVirtualChildCount(
				uint32_t parentId) override
			{
				return _owner.GetAccessibilityVirtualChildCount(parentId);
			}
			bool TryGetAccessibilityVirtualChildAt(
				uint32_t parentId, size_t index, uint32_t& result) override
			{
				return _owner.TryGetAccessibilityVirtualChildAt(
					parentId, index, result);
			}
			bool TryGetAccessibilityVirtualSibling(
				uint32_t parentId, uint32_t id, bool next,
				uint32_t& result) override
			{
				return _owner.TryGetAccessibilityVirtualSibling(
					parentId, id, next, result);
			}
			bool TryHitTestAccessibilityVirtualNode(
				float localX, float localY, uint32_t& result) override
			{
				return _owner.TryHitTestAccessibilityVirtualNode(
					localX, localY, result);
			}

		private:
			IndexedVirtualProbe& _owner;
		};

	protected:
		std::unique_ptr<AutomationPeer> OnCreateAutomationPeer() override
		{
			return std::make_unique<Peer>(*this);
		}
	};

