	class TokenOnlyBindingSource final : public IBindingSource
	{
	public:
		struct Entry final
		{
			BindingSourcePropertyToken Property;
			BindingValue Value;
			bool CanWrite = true;
			mutable size_t ReadCalls = 0;
		};

		void Define(
			BindingSourcePropertyToken property,
			BindingValue value,
			bool canWrite = true)
		{
			Entries.push_back({ property, std::move(value), canWrite });
		}

		bool Set(BindingSourcePropertyToken property, BindingValue value)
		{
			auto* entry = Find(property);
			if (!entry) return false;
			entry->Value = std::move(value);
			Changed.Notify(property);
			return true;
		}

		bool TryGetValue(
			BindingSourcePropertyToken property,
			BindingValue& out) const override
		{
			++TokenGetCalls;
			const auto* entry = Find(property);
			if (!entry) return false;
			++entry->ReadCalls;
			out = entry->Value;
			if (ReadCallback)
			{
				auto callback = std::move(ReadCallback);
				callback(property);
			}
			return true;
		}

		size_t ReadCallsFor(BindingSourcePropertyToken property) const noexcept
		{
			const auto* entry = Find(property);
			return entry ? entry->ReadCalls : 0;
		}

		void ResetReadCalls() const noexcept
		{
			for (const auto& entry : Entries) entry.ReadCalls = 0;
		}

		bool TrySetValue(
			BindingSourcePropertyToken property,
			const BindingValue& value) override
		{
			++TokenSetCalls;
			auto* entry = Find(property);
			if (!entry || !entry->CanWrite) return false;
			entry->Value = value;
			Changed.Notify(property);
			return true;
		}

		bool TryGetPropertyMetadata(
			BindingSourcePropertyToken property,
			BindingSourcePropertyMetadata& out) const override
		{
			++TokenMetadataCalls;
			const auto* entry = Find(property);
			if (!entry) return false;
			out = { {}, entry->Value.Kind(),
				std::type_index(entry->Value.Type()), true,
				entry->CanWrite, true };
			return true;
		}

		bool TryGetValue(
			const std::wstring&, BindingValue&) const override
		{
			++NameGetCalls;
			return false;
		}

		bool TrySetValue(
			const std::wstring&, const BindingValue&) override
		{
			++NameSetCalls;
			return false;
		}

		bool TryGetPropertyMetadata(
			const std::wstring&,
			BindingSourcePropertyMetadata&) const override
		{
			++NameMetadataCalls;
			return false;
		}

		std::vector<BindingSourcePropertyMetadata> GetProperties() const override
		{
			++DiscoveryCalls;
			return {};
		}

		PropertyChangedEvent& PropertyChanged() override { return Changed; }

		mutable int TokenGetCalls = 0;
		int TokenSetCalls = 0;
		mutable int TokenMetadataCalls = 0;
		mutable int NameGetCalls = 0;
		int NameSetCalls = 0;
		mutable int NameMetadataCalls = 0;
		mutable int DiscoveryCalls = 0;
		mutable std::function<void(BindingSourcePropertyToken)> ReadCallback;

	private:
		Entry* Find(BindingSourcePropertyToken property)
		{
			const auto found = std::find_if(
				Entries.begin(), Entries.end(), [&](const auto& entry)
				{
					return entry.Property == property;
				});
			return found == Entries.end() ? nullptr : &*found;
		}

		const Entry* Find(BindingSourcePropertyToken property) const
		{
			const auto found = std::find_if(
				Entries.begin(), Entries.end(), [&](const auto& entry)
				{
					return entry.Property == property;
				});
			return found == Entries.end() ? nullptr : &*found;
		}

		std::vector<Entry> Entries;
		PropertyChangedEvent Changed;
	};

    class MetadataBindingControl final : public Control
    {
    public:
        BindingPayload Payload;
        PropertyChangedEvent MetadataChanged;

        void EnsureBindingPropertiesRegistered() override
        {
            Control::EnsureBindingPropertiesRegistered();
            static const bool registered = []
            {
                DependencyPropertyRegistry::Register<MetadataBindingControl, BindingPayload>(
                    L"Payload",
                    [](MetadataBindingControl& target) { return target.Payload; },
                    [](MetadataBindingControl& target, const BindingPayload& value)
                    {
                        target.SetPayload(value);
                    },
                    [](MetadataBindingControl& target,
						DependencyPropertyMetadata::ChangeHandler handler,
						DataSourceUpdateMode)
					{
						return target.MetadataChanged.Subscribe(
							[handler = std::move(handler)](const PropertyChangedEventArgs&) { handler(); });
					});
                return true;
            }();
            (void)registered;
        }

        void SetPayload(BindingPayload value)
        {
            if (Payload == value) return;
            Payload = std::move(value);
            MetadataChanged.Notify(L"Payload");
        }
    };

	class PropertySystemControl final : public Control
	{
	private:
		int _level = 4;

	public:
		int ChangedCallbackCount = 0;
		int MaximumLevel = 10;
		UIClass Type() override { return UIClass::UI_CUSTOM; }
		int GetLevel() const noexcept { return _level; }
		void SetLevel(int value)
		{
			SetPropertyField(L"Level", _level, value);
		}
		void SetCurrentLevel(int value)
		{
			SetCurrentPropertyField(L"Level", _level, value);
		}

		void EnsureBindingPropertiesRegistered() override
		{
			Control::EnsureBindingPropertiesRegistered();
			static const bool registered = []
			{
				DependencyPropertyOptions<PropertySystemControl, int> options;
				options.DefaultValue = 4;
				options.Flags = DependencyPropertyFlags::AffectsMeasure
					| DependencyPropertyFlags::AffectsRender;
				options.Coerce = [](
					PropertySystemControl& target, const int& proposed)
					-> std::optional<int>
				{
					return (std::clamp)(
						proposed, 0, (std::max)(0, target.MaximumLevel));
				};
				options.Changed = [](
					PropertySystemControl& target, const int&, const int&)
				{
					++target.ChangedCallbackCount;
				};
				options.Validate = [](const int& value)
				{
					return value >= -100 && value <= 100;
				};
				DependencyPropertyRegistry::Register<PropertySystemControl, int>(
					L"Level",
					[](PropertySystemControl& target) { return target.GetLevel(); },
					[](PropertySystemControl& target, const int& value)
					{
						target.SetLevel(value);
					},
					[](PropertySystemControl& target,
						DependencyPropertyMetadata::ChangeHandler handler,
						DataSourceUpdateMode)
					{
						return target.OnPropertyValueChanged.Subscribe(
							[handler = std::move(handler)](
								DependencyObject*, const DependencyPropertyChangedEventArgs& e)
							{
								if (e.Name() == L"Level") handler();
							});
					},
					std::move(options));
				return true;
			}();
			(void)registered;
		}
	};

	class PropertySystemObject final : public DependencyObject
	{
	private:
		int _quantity = 2;

	public:
		int MaximumQuantity = 10;
		int ChangedCallbackCount = 0;

		int GetQuantity() const noexcept { return _quantity; }
		void SetQuantity(int value)
		{
			SetPropertyField(L"Quantity", _quantity, value);
		}

		void EnsureBindingPropertiesRegistered() override
		{
			static const bool registered = []
			{
				DependencyPropertyOptions<PropertySystemObject, int> options;
				options.DefaultValue = 2;
				options.Validate = [](const int& value)
				{
					return value >= 0 && value <= 20;
				};
				options.Coerce = [](
					PropertySystemObject& target, const int& proposed)
					-> std::optional<int>
				{
					return (std::min)(
						proposed, (std::max)(0, target.MaximumQuantity));
				};
				options.Changed = [](
					PropertySystemObject& target, const int&, const int&)
				{
					++target.ChangedCallbackCount;
				};
				DependencyPropertyRegistry::Register<PropertySystemObject, int>(
					L"Quantity",
					[](PropertySystemObject& target)
					{
						return target.GetQuantity();
					},
					[](PropertySystemObject& target, const int& value)
					{
						target.SetQuantity(value);
					},
					{},
					std::move(options));
				return true;
			}();
			(void)registered;
		}
	};

