		combo.GetAutomationPeer().GetAccessibilityVirtualChildren(0, comboIds);
		CUI_EXPECT_EQ(betaId, comboIds[2]);
		CUI_EXPECT_TRUE(combo.MoveItemControl(2, 0));
		CUI_EXPECT_EQ(0, combo.SelectedIndex);
		combo.GetAutomationPeer().GetAccessibilityVirtualChildren(0, comboIds);
		CUI_EXPECT_EQ(betaId, comboIds[0]);
		SetTestComboBoxItems(
			combo, { L"Beta", L"Zero", L"Alpha", L"Gamma", L"Delta" });
		CUI_EXPECT_EQ(std::wstring(L"Beta"), combo.Text);

		TreeView tree; ConfigureTestControl(tree, 0, 0, 240, 120);
		auto parentOwner = std::make_unique<TreeViewItem>();
		parentOwner->SetHeader(BindingValue(std::wstring(L"Parent")));
		auto* parent = static_cast<TreeViewItem*>(
			tree.AddItemControl(std::move(parentOwner)));
		CUI_EXPECT_TRUE(parent != nullptr);
		auto childOwner = std::make_unique<TreeViewItem>();
		childOwner->SetHeader(BindingValue(std::wstring(L"Child")));
		auto* child = static_cast<TreeViewItem*>(
			parent->AddItemControl(std::move(childOwner)));
