	runner.Add("Collection controls expose scrolling through their viewport owner", []
	{
		Window host; ConfigureTestControl(host, L"ComboBox viewport owner");
		SetDeclaredWindowGeometry(host, 0.0f, 0.0f, 320.0f, 180.0f);
		auto contentOwner = MakeTestControl<Panel>();
		auto* content = static_cast<Panel*>(
			host.SetVisualContent(std::move(contentOwner)));
		AccessibilityScrollInfo scrollInfo;
		auto* combo = AddTestVisual<ComboBox>(*content, L"", 0, 0, 160, 28);
		combo->MaxDropDownHeight = 56.0f;
		SetTestComboBoxItems(*combo, {
			L"One", L"Two", L"Three", L"Four", L"Five", L"Six",
			L"Seven", L"Eight", L"Nine", L"Ten", L"Eleven", L"Twelve" });
		host.UpdateLayout();
		combo->SetIsDropDownOpen(true);
		host.UpdateLayout();
		ScrollViewer* comboScroll = nullptr;
		auto findComboScroll = [&](Control* current, const auto& self) -> void
		{
			if (!current || comboScroll) return;
			if (auto* scroll = dynamic_cast<ScrollViewer*>(current))
			{
				comboScroll = scroll;
				return;
			}
			for (auto* child : current->GetVisualChildrenView())
				self(child, self);
		};
		findComboScroll(combo, findComboScroll);
		CUI_EXPECT_TRUE(comboScroll != nullptr);
		auto* comboPopup = dynamic_cast<Popup*>(
			TemplateAccess::GetTemplateRoot(*combo));
		CUI_EXPECT_TRUE(comboPopup != nullptr);
		CUI_EXPECT_TRUE(comboPopup && comboPopup->GetIsOpen());
		CUI_EXPECT_TRUE(comboPopup
			&& comboPopup->GetPresentationWindow() == &host);
		CUI_EXPECT_NEAR(56.0f,
			comboPopup ? comboPopup->ActualHeight : 0.0f, 0.001f);
		if (comboScroll)
		{
			CUI_EXPECT_NEAR(56.0f, comboScroll->MaxHeight, 0.001f);
			CUI_EXPECT_NEAR(56.0f, comboScroll->ActualHeight, 0.001f);
			CUI_EXPECT_TRUE(comboScroll->ExtentHeight
				> comboScroll->ViewportHeight);
		}
		auto& comboPeer = combo->GetAutomationPeer();
		CUI_EXPECT_TRUE(comboPeer.GetAccessibilityScrollInfo(scrollInfo));
		CUI_EXPECT_TRUE(scrollInfo.VerticallyScrollable);
		CUI_EXPECT_TRUE(comboPeer.ScrollAccessibility(
			AccessibilityScrollAmount::NoAmount,
			AccessibilityScrollAmount::LargeIncrement));
		CUI_EXPECT_TRUE(combo->GetIsDropDownOpen());
		CUI_EXPECT_TRUE(comboPeer.SetAccessibilityScrollPercent(
			AccessibilityScrollNoChange, 100.0));
		CUI_EXPECT_TRUE(comboPeer.GetAccessibilityScrollInfo(scrollInfo));
		CUI_EXPECT_TRUE(scrollInfo.VerticalScrollPercent >= 99.0);

		TreeView tree; ConfigureTestControl(tree, 0, 0, 160, 56);
		auto treePanel = std::make_shared<ItemsPanelTemplate>();
		treePanel->Kind = ItemsPanelKind::VirtualizingStack;
		treePanel->ItemHeight = 28.0f;
		treePanel->CacheLength = 0.0f;
		tree.SetItemsPanel(ItemsPanelTemplateReference(treePanel));
		auto* treeScroll = InstallItemsScrollTemplate(tree);
		auto treeItems = std::make_shared<ObservableBindingList>(L"TreeEntry");
		for (int index = 0; index < 32; ++index)
		{
			auto item = std::make_shared<ObservableObject>();
			CUI_EXPECT_TRUE(item->DefineProperty(
				L"Name", L"Node " + std::to_wstring(index)));
			treeItems->Items.push_back(BindingSourceReference(item));
		}
		tree.SetDisplayMemberPath(L"Name");
		tree.SetItemsSource(BindingListReference(treeItems));
		tree.Arrange(cui::core::Rect{ 0.0f, 0.0f, 160.0f, 56.0f });
		tree.UpdateLayout();
		CUI_EXPECT_TRUE(tree.IsVirtualizing());
		CUI_EXPECT_TRUE(tree.GeneratedItemCount() < tree.ItemCount());
		CUI_EXPECT_EQ(0.0, treeScroll->VerticalOffset);
		treeScroll->ScrollToVerticalOffset(56.0);
		CUI_EXPECT_TRUE(treeScroll->VerticalOffset > 0.0);
		treeScroll->ScrollToHome();
		CUI_EXPECT_EQ(0.0, treeScroll->VerticalOffset);

	});

