		CUI_EXPECT_EQ(6, target.GetLevel());
		CUI_EXPECT_EQ(DependencyPropertyValueSource::Theme,
			target.GetPropertyValueSource(L"Level"));

		// ToolBar applies its type-specific theme resource as Style.  The
