		const auto indexOf = [&](const wchar_t* name)
		{
			for (size_t index = 0; index < browsable.size(); ++index)
				if (browsable[index].Name == name)
					return static_cast<int>(index);
			return -1;
		};
		const int widthIndex = indexOf(L"Width");
		const int roundIndex = indexOf(L"FontSize");
		CUI_EXPECT_TRUE(widthIndex >= 0);
		CUI_EXPECT_TRUE(roundIndex > widthIndex);
		CUI_EXPECT_EQ(-1, indexOf(L"IsChecked"));
		CUI_EXPECT_EQ(std::wstring(L"Width"),
			browsable[static_cast<size_t>(widthIndex)].DisplayName);
		CUI_EXPECT_EQ(-1, indexOf(L"LayoutWidth"));
		CUI_EXPECT_EQ(-1, indexOf(L"Visibility"));
		CUI_EXPECT_EQ(-1, indexOf(L"Background"));

