		{
			auto name = row.Name;
			std::transform(name.begin(), name.end(), name.begin(), towlower);
			CUI_EXPECT_TRUE(actualNames.insert(std::move(name)).second);
		}

		const auto* name = DesignerPropertyRowCatalog::Find(rows, L"Name");
		const auto* locked = DesignerPropertyRowCatalog::Find(rows, L"Locked");
		const auto* fontSize = DesignerPropertyRowCatalog::Find(rows, L"FontSize");
		const auto* fontName = DesignerPropertyRowCatalog::Find(rows, L"FontFamily");
		const auto* horizontal = DesignerPropertyRowCatalog::Find(rows, L"HorizontalAlignment");
