		targetTranslation.X = 34.0f;
		targetTranslation.Y = 9.0f;
		targetTransform.Operations.push_back(targetTranslation);
		combo->SetRenderTransform(targetTransform);
		host.UpdateLayout();
		combo->SetIsDropDownOpen(true);
