		{
			menu.InsertVisualChild(
				menu.VisualChildCount(), invalidMenuChild.get());
		}
		catch (const std::logic_error&)
		{
			invalidMenuChildRejected = true;
		}
		CUI_EXPECT_TRUE(invalidMenuChildRejected);
		CUI_EXPECT_TRUE(invalidMenuChild->GetVisualParent() == nullptr);

		auto* open = AddTestMenuItem(*file, L"Open", L"Test.File.Open");
