	runner.Add("NotifyIcon projects tray leaves into routed commands", []
	{
		auto root = NotifyIconMenuItem::Submenu(L"操作");
		CUI_EXPECT_TRUE(root.AddItem(NotifyIconMenuItem(
			L"打开窗口", RoutedCommand(L"ShowWindow"))));
		CUI_EXPECT_TRUE(root.AddItem(NotifyIconMenuItem(
			L"暂停任务", RoutedCommand(L"TogglePause"), std::wstring(L"job-7"), false)));
		CUI_EXPECT_FALSE(root.AddItem(NotifyIconMenuItem{}));
		NotifyIconMenuItem copiedRoot = root;
		CUI_EXPECT_EQ(std::wstring(L"打开窗口"), copiedRoot.Items[0].Text);
		CUI_EXPECT_EQ(std::wstring(L"ShowWindow"),
			copiedRoot.Items[0].Command.Name());
		CUI_EXPECT_FALSE(copiedRoot.Items[1].IsEnabled);

		NotifyIcon icon;
		Window owner;
		CUI_EXPECT_FALSE(icon.IsInitialized());
		CUI_EXPECT_FALSE(icon.IsVisible());
		CUI_EXPECT_TRUE(icon.TrySetToolTip(L"CUI 通知中心"));
		CUI_EXPECT_EQ(std::wstring(L"CUI 通知中心"), icon.GetToolTip());
		CUI_EXPECT_TRUE(icon.TryInitialize(owner));
		CUI_EXPECT_TRUE(icon.GetOwner() == &owner);
		CUI_EXPECT_FALSE(icon.TryShow());
		CUI_EXPECT_EQ(E_POINTER, icon.GetLastError());
		CUI_EXPECT_TRUE(icon.TryHide());

		CUI_EXPECT_TRUE(icon.TryAddMenuItem(copiedRoot));
		CUI_EXPECT_TRUE(icon.TryAddMenuSeparator());
		CUI_EXPECT_TRUE(icon.TryAddMenuItem(
			NotifyIconMenuItem(L"退出", RoutedCommand(L"Exit"))));
		CUI_EXPECT_EQ(3ULL, icon.MenuItemCount());
		CUI_EXPECT_EQ(5ULL, icon.MenuItemCount(true));
		CUI_EXPECT_FALSE(icon.TryAddMenuItem(
			NotifyIconMenuItem{}));
		CUI_EXPECT_EQ(E_INVALIDARG, icon.GetLastError());
		CUI_EXPECT_EQ(std::wstring(L"操作"), icon.GetMenuItems()[0].Text);
		CUI_EXPECT_TRUE(icon.TryRemoveMenuItemAt(1));
		CUI_EXPECT_EQ(2ULL, icon.MenuItemCount());
		CUI_EXPECT_FALSE(icon.TryRemoveMenuItemAt(99));
		CUI_EXPECT_TRUE(FAILED(icon.GetLastError()));

		auto more = NotifyIconMenuItem::Submenu(L"更多");
		CUI_EXPECT_TRUE(more.AddItem(NotifyIconMenuItem(
			L"诊断", RoutedCommand(L"Diagnostics"))));
		CUI_EXPECT_TRUE(icon.TryAddMenuItem(std::move(more)));
		CUI_EXPECT_EQ(6ULL, icon.MenuItemCount(true));

		icon.ClearMenu();
		CUI_EXPECT_EQ(0ULL, icon.MenuItemCount());
		CUI_EXPECT_FALSE(icon.TryShowContextMenu(0, 0));
		CUI_EXPECT_EQ(E_INVALIDARG, icon.GetLastError());
	});

