		CUI_EXPECT_TRUE(earlier->HandlesNavigationKey(Key::Space));
		CUI_EXPECT_FALSE(earlier->HandlesNavigationKey(Key::Return));
		auto& buttonPeer = earlier->GetAutomationPeer();
