		CUI_EXPECT_TRUE(checkBox.IsChecked);
		CUI_EXPECT_EQ(1, checkedEvents);
		CUI_EXPECT_EQ(0, uncheckedEvents);
		CUI_EXPECT_TRUE(checkBox.Invoke());
		CUI_EXPECT_FALSE(checkBox.IsChecked);
		CUI_EXPECT_EQ(1, checkedEvents);
		CUI_EXPECT_EQ(1, uncheckedEvents);
		auto& checkPeer = checkBox.GetAutomationPeer();
