		CUI_EXPECT_EQ(std::wstring(L"Account password"), passwordSnapshot.Name);
		CUI_EXPECT_EQ(std::wstring(L"accountPassword"), passwordSnapshot.AutomationId);
		CUI_EXPECT_EQ(AutomationControlType::Edit, passwordSnapshot.ControlType);
		auto& passwordPeer = password.GetAutomationPeer();
		CUI_EXPECT_TRUE(passwordPeer.SupportsPattern(AutomationPattern::Value));
		CUI_EXPECT_TRUE(passwordPeer.IsPassword());
		CUI_EXPECT_TRUE(passwordPeer.GetValue().empty());

		Slider slider; ConfigureTestControl(slider, 0, 0, 120, 24);
		auto& sliderPeer = slider.GetAutomationPeer();
		CUI_EXPECT_EQ(AutomationControlType::Slider,
			sliderPeer.GetAutomationControlType());
