		CUI_EXPECT_TRUE(focusWithinMetadata
			&& focusWithinMetadata->IsReadOnly());
		CUI_EXPECT_TRUE(accessibleNameMetadata != nullptr);
		CUI_EXPECT_TRUE(roleMetadata == nullptr);
		for (const wchar_t* removed : { L"AccessKey", L"BackColor",
			L"ForeColor", L"BorderColor", L"FocusedColor",
			L"FocusBorderColor" })
			CUI_EXPECT_TRUE(earlier->FindPropertyMetadata(removed) == nullptr);
		CUI_EXPECT_EQ(BindingValueKind::Int, tabIndexMetadata->ValueKind());
		CUI_EXPECT_EQ(BindingValueKind::String, accessibleNameMetadata->ValueKind());
