		CUI_EXPECT_EQ(std::wstring(L"Background"),
			document.ControlTemplates.front().Template.front()
				.TemplateBindings.at(L"Background"));
		const auto buttonNode = std::find_if(document.Nodes.begin(),
			document.Nodes.end(), [](const auto& node)
			{ return node.Name == L"templatedButton"; });
		CUI_EXPECT_TRUE(buttonNode != document.Nodes.end());
		CUI_EXPECT_EQ(std::wstring(L"AccentButtonTemplate"),
			buttonNode->Structure.ControlTemplate);

		CuiRuntime::XamlObjectTree tree;
