		expectSize(readExtent(), { 12.75f, 24.25f });

		(void)go(L"Idle");
		tick = go(L"Additive");
		CUI_EXPECT_TRUE(cui::framework::PresentationAccess::AdvanceVisualStateAnimations(*card, tick + 150));
		expectSize(readExtent(), { 14.75f, 26.0f }, 0.35f);

		(void)go(L"Idle");
		tick = go(L"Simple", true);
