		CUI_EXPECT_NEAR(10.0f, geometryMatrix()._31, 0.2f);
		CUI_EXPECT_NEAR(1.125f, brushMatrix(false)._11, 0.08f);
		CUI_EXPECT_NEAR(0.75f, brushMatrix(true)._11, 0.08f);
