		CUI_EXPECT_TRUE(renderMatrix()._11 > 1.0f && renderMatrix()._11 < 2.0f);
		CUI_EXPECT_TRUE(cui::framework::PresentationAccess::AdvanceVisualStateAnimations(*card, tick + 100));
		CUI_EXPECT_NEAR(2.0f, renderMatrix()._11, 0.001f);

