		const auto* parsedMenu = findParsedNode(L"mainMenu");
		const auto* parsedOutlineRoot = findParsedNode(L"outlineRoot");
		const auto* parsedOutlineChild = findParsedNode(L"outlineChild");
		const auto* parsedFileItem = findParsedNode(L"fileMenuItem");
		const auto* parsedOpenItem = findParsedNode(L"openMenuItem");
		const auto* parsedSeparator = findParsedNode(L"fileSeparator");
