	runner.Add("NumericUpDown input survives ValueChanged owner deletion", []
	{
		struct NumericInputLifetimeProbe final : NumericUpDown
		{
			void RefreshTemplateParts()
			{
				OnControlTemplatePresentationChanged();
			}
		};

		Window inputHost;
		ConfigureTestControl(inputHost, L"Numeric input lifetime");
		SetDeclaredWindowGeometry(
			inputHost, 0.0f, 0.0f, 220.0f, 100.0f);
		auto rootOwner = MakeTestControl<Panel>(
			0.0f, 0.0f, 220.0f, 100.0f);
		auto* root = rootOwner.get();
		CUI_EXPECT_TRUE(
			inputHost.SetVisualContent(std::move(rootOwner)) == root);

		auto* commitOwner = AddTestVisual<NumericInputLifetimeProbe>(
			*root, 0.0f, 0.0f, 140.0f, 30.0f);
		commitOwner->Arrange(cui::core::Rect{
			0.0f, 0.0f, 140.0f, 30.0f });
		auto* editor = AddTestVisual<TextBox>(
			*commitOwner, 0.0f, 0.0f, 112.0f, 30.0f);
		cui::framework::XamlAccess::SetTemplatedParent(
			*editor, commitOwner);
		CUI_EXPECT_TRUE(cui::framework::XamlAccess::RegisterTemplatePart(
			*commitOwner, MakeTemplatePartToken(L"PART_TextBox"), editor));
		commitOwner->RefreshTemplateParts();
		editor->SelectAll();
		TextCompositionEventArgs replacement(L"5");
		CUI_EXPECT_TRUE(cui::framework::InputAccess::DispatchTextInput(
			*commitOwner, replacement));
		CUI_EXPECT_EQ(std::wstring(L"5"), editor->Text);

		const ControlWeakReference commitLifetime(commitOwner);
		bool commitDeleted = false;
		auto commitDeletion = commitOwner->ValueChanged.Subscribe(
			[&](Control*, RoutedPropertyChangedEventArgs<double>&)
			{
				if (!commitOwner) return;
				auto* doomed = commitOwner;
				commitOwner = nullptr;
				commitDeleted = root->DeleteVisualChild(doomed);
			});
		auto* commitTarget = commitOwner;
		CUI_EXPECT_TRUE(cui::framework::InputAccess::DispatchInput(
			*commitTarget,
			KeyInput(InputReportKind::KeyDown, Key::Return)));
		CUI_EXPECT_TRUE(commitDeleted);
		CUI_EXPECT_TRUE(commitOwner == nullptr);
		CUI_EXPECT_FALSE(commitLifetime);

		auto* spinOwner = AddTestVisual<NumericUpDown>(
			*root, 0.0f, 40.0f, 140.0f, 30.0f);
		spinOwner->Arrange(cui::core::Rect{
			0.0f, 40.0f, 140.0f, 30.0f });
		const ControlWeakReference spinLifetime(spinOwner);
		bool spinDeleted = false;
		auto spinDeletion = spinOwner->ValueChanged.Subscribe(
			[&](Control*, RoutedPropertyChangedEventArgs<double>&)
			{
				if (!spinOwner) return;
				auto* doomed = spinOwner;
				spinOwner = nullptr;
				spinDeleted = root->DeleteVisualChild(doomed);
			});
		auto* spinTarget = spinOwner;
		CUI_EXPECT_TRUE(cui::framework::InputAccess::DispatchInput(
			*spinTarget,
			PointerInput(
				InputReportKind::PointerDown, MouseButton::Left,
				135, 5, MouseButton::Left)));
		CUI_EXPECT_TRUE(spinDeleted);
		CUI_EXPECT_TRUE(spinOwner == nullptr);
		CUI_EXPECT_FALSE(spinLifetime);
		CUI_EXPECT_TRUE(inputHost.GetMouseCaptured() == nullptr);
	});

	runner.Add("Designer document graph centralizes identity parent and order resolution", []
	{
		DesignerModel::DesignDocument document;
		document.NextStableId = 40;
		DesignerModel::DesignNode lateChild;
		lateChild.Id = 30;
		lateChild.ParentId = 10;
		lateChild.ParentRef = L"container";
		lateChild.Name = L"lateChild";
		lateChild.Type = UIClass::UI_Button;
		lateChild.Order = 2;
		document.Nodes.push_back(std::move(lateChild));
		DesignerModel::DesignNode parent;
		parent.Id = 10;
		parent.Name = L"container";
		parent.Type = UIClass::UI_Canvas;
		parent.Order = 0;
		document.Nodes.push_back(std::move(parent));
		DesignerModel::DesignNode earlyChild;
		earlyChild.Id = 20;
		earlyChild.ParentId = 10;
		earlyChild.ParentRef = L"container";
		earlyChild.Name = L"earlyChild";
		earlyChild.Type = UIClass::UI_Button;
		earlyChild.Order = 1;
		document.Nodes.push_back(std::move(earlyChild));

		DesignerModel::DesignDocumentGraph graph;
		std::wstring error;
		CUI_EXPECT_TRUE(DesignerModel::DesignDocumentGraph::Build(
			document, graph, &error));
		CUI_EXPECT_EQ(30, graph.MaxStableId());
		CUI_EXPECT_EQ(1ULL, graph.Roots().size());
		CUI_EXPECT_EQ(1ULL, graph.Roots()[0]);
		const auto children = graph.ChildrenOf(L"container");
		CUI_EXPECT_EQ(2ULL, children.size());
		CUI_EXPECT_EQ(2ULL, children[0]);
		CUI_EXPECT_EQ(0ULL, children[1]);
		CUI_EXPECT_EQ(0ULL, graph.FindById(30)->SourceIndex);
		CUI_EXPECT_EQ(2ULL,
			graph.FindByName(L"earlyChild")->SourceIndex);
		CUI_EXPECT_EQ(std::wstring(L"container"),
			graph.Nodes()[0].ParentKey);

		auto missingParentId = document;
		missingParentId.Nodes.front().ParentId = 0;
		CUI_EXPECT_FALSE(DesignerModel::DesignDocumentGraph::Build(
			missingParentId, graph, &error));
		auto negativeParentId = document;
		negativeParentId.Nodes[1].ParentId = -1;
		CUI_EXPECT_FALSE(DesignerModel::DesignDocumentGraph::Build(
			negativeParentId, graph, &error));
	});

	runner.Add("Designer materialization pool owns rollback and transfers controls", []
	{
		struct TrackedControl final : Control
		{
			explicit TrackedControl(int& destroyed) : Destroyed(&destroyed) {}
			~TrackedControl() override { ++*Destroyed; }
			int* Destroyed;
		};

		DesignerModel::DesignDocument document;
		for (int id = 1; id <= 3; ++id)
		{
			DesignerModel::DesignNode node;
			node.Id = id;
			node.Name = L"control" + std::to_wstring(id);
			node.Type = UIClass::UI_Button;
			document.Nodes.push_back(std::move(node));
		}
		document.NextStableId = 4;
		DesignerModel::DesignDocumentGraph graph;
		std::wstring error;
		CUI_EXPECT_TRUE(DesignerModel::DesignDocumentGraph::Build(
			document, graph, &error));

		int destroyed = 0;
		{
			DesignerModel::DesignDocumentControlPool pool;
			CUI_EXPECT_TRUE(DesignerModel::DesignDocumentControlPool::Build(
				document, graph,
				[&](const DesignerModel::DesignNode&)
				{ return std::make_unique<TrackedControl>(destroyed); },
				pool, &error));
			CUI_EXPECT_EQ(3ULL, pool.PendingCount());
			CUI_EXPECT_EQ(pool.FindById(2), pool.FindByName(L"control2"));

			Control runtimeRoot;
			auto attached = pool.TakeByName(L"control2");
			CUI_EXPECT_TRUE(attached != nullptr);
			auto* attachedControl = attached.get();
			runtimeRoot.AddOwned(std::move(attached));
			CUI_EXPECT_EQ(2ULL, pool.PendingCount());
			CUI_EXPECT_EQ(attachedControl, runtimeRoot.GetVisualChild(0));
		}
		CUI_EXPECT_EQ(3, destroyed);

		DesignerModel::DesignDocumentControlPool rejected;
		CUI_EXPECT_FALSE(DesignerModel::DesignDocumentControlPool::Build(
			document, graph,
			[](const DesignerModel::DesignNode&)
			{ return std::unique_ptr<Control>{}; },
			rejected, &error));
		CUI_EXPECT_EQ(0ULL, rejected.PendingCount());
	});

