	runner.Add("ChartView owns pointer input beneath decorative template chrome", []
	{
		Window host;
		ConfigureTestControl(host, L"ChartView template input");
		SetDeclaredWindowGeometry(
			host, 0.0f, 0.0f, 320.0f, 220.0f);
		auto contentOwner = MakeTestControl<Canvas>();
		auto* content = static_cast<Canvas*>(
			host.SetVisualContent(std::move(contentOwner)));
		auto chartOwner = MakeTestControl<ChartView>(
			20.0f, 20.0f, 260.0f, 160.0f);
		auto* chart = chartOwner.get();
		chart->ChartKind = ChartViewKind::Line;
		chart->Title = L"";
		chart->ShowLegend = false;
		chart->SetSingleSeries({ ChartPoint{ L"Q1", 10.0 } });
		cui::drawing::Transform chartTransform;
		cui::drawing::TransformOperation chartScale;
		chartScale.Kind = cui::drawing::TransformKind::Scale;
		chartScale.ScaleX = 1.04f;
		chartScale.ScaleY = 1.04f;
		cui::drawing::TransformOperation chartRotation;
		chartRotation.Kind = cui::drawing::TransformKind::Rotate;
		chartRotation.Angle = 4.0f;
		chartTransform.Operations = { chartScale, chartRotation };
		chart->SetRenderTransformOrigin(D2D1::Point2F(0.5f, 0.5f));
		chart->SetRenderTransform(chartTransform);

		// Mirror Generic.xaml's full-size Grid -> transparent Border chrome.
		// ChartView paints and interacts with its data points itself, so this
		// decoration must not become the direct pointer-input target.
		auto templateRoot = MakeTestControl<Grid>();
		auto* templateRootPointer = templateRoot.get();
		auto chromeOwner = MakeTestControl<Border>();
		auto* chrome = chromeOwner.get();
		cui::framework::TreeAccess::SetTemplatedParent(
			*templateRootPointer, chart);
		cui::framework::TreeAccess::SetTemplatedParent(*chrome, chart);
		templateRootPointer->AddOwned(std::move(chromeOwner));
		CUI_EXPECT_TRUE(cui::framework::TemplateAccess::SetTemplateRoot(
			*chart, std::move(templateRoot)) == templateRootPointer);
		content->AddOwned(std::move(chartOwner));
		host.UpdateLayout();

		CUI_EXPECT_FALSE(chart->HitTestChildren());
		CUI_EXPECT_TRUE(chrome->GetActualSizeDip().width > 0.0f);
		CUI_EXPECT_TRUE(chrome->GetActualSizeDip().height > 0.0f);
		uint32_t virtualPointId = 0;
		AccessibilityVirtualNode virtualPoint;
		CUI_EXPECT_TRUE(chart->TryGetAccessibilityVirtualChildAt(
			0, 0, virtualPointId));
		CUI_EXPECT_TRUE(chart->TryGetAccessibilityVirtualNode(
			virtualPointId, virtualPoint));
		const int localX = static_cast<int>(
			(virtualPoint.BoundsDip.left
				+ virtualPoint.BoundsDip.right) * 0.5f);
		const int localY = static_cast<int>(
			(virtualPoint.BoundsDip.top
				+ virtualPoint.BoundsDip.bottom) * 0.5f);
		int seriesIndex = -1;
		int pointIndex = -1;
		CUI_EXPECT_TRUE(chart->HitTestPoint(
			localX, localY, seriesIndex, pointIndex));
		CUI_EXPECT_EQ(0, seriesIndex);
		CUI_EXPECT_EQ(0, pointIndex);

		const auto rawTransform = chart->GetLocalToRenderTransform();
		const auto renderPoint = D2D1::Matrix3x2F(
			rawTransform._11, rawTransform._12,
			rawTransform._21, rawTransform._22,
			rawTransform._31, rawTransform._32)
			.TransformPoint(D2D1::Point2F(
				static_cast<float>(localX), static_cast<float>(localY)));
		const float contentX = renderPoint.x;
		const float contentY = renderPoint.y;
		auto* hit = cui::framework::WindowAccess::HitTestControlAt(
			host, static_cast<int>(std::lround(contentX)),
			static_cast<int>(std::lround(contentY)));
		CUI_EXPECT_TRUE(hit == chart);

		int clickCount = 0;
		auto pointClick = chart->OnPointClick.Subscribe(
			[&](ChartView* sender, int series, int point)
			{
				CUI_EXPECT_TRUE(sender == chart);
				CUI_EXPECT_EQ(0, series);
				CUI_EXPECT_EQ(0, point);
				++clickCount;
			});
		CUI_EXPECT_TRUE(host.Handle != nullptr);
		const auto clientPoint = host.ContentDipRectToClientPixels(
			D2D1::RectF(contentX, contentY, contentX + 1.0f, contentY + 1.0f));
		const int clientX = (clientPoint.left + clientPoint.right) / 2;
		const int clientY = (clientPoint.top + clientPoint.bottom) / 2;
		const LPARAM pointerPoint = MAKELPARAM(clientX, clientY);
		(void)::SendMessageW(
			host.Handle, WM_LBUTTONDOWN, MK_LBUTTON, pointerPoint);
		(void)::SendMessageW(host.Handle, WM_LBUTTONUP, 0, pointerPoint);
		CUI_EXPECT_EQ(1, clickCount);
		CUI_EXPECT_EQ(0, chart->GetSelectedSeriesIndex());
		CUI_EXPECT_EQ(0, chart->GetSelectedPointIndex());

		chart->SetSingleSeries({
			ChartPoint{ L"Q1", 10.0 }, ChartPoint{ L"Q2", 12.0 },
			ChartPoint{ L"Q3", 9.0 }, ChartPoint{ L"Q4", 14.0 },
			ChartPoint{ L"Q5", 11.0 }, ChartPoint{ L"Q6", 15.0 } });
		const float oldZoom = chart->GetZoomX();
		POINT wheelPoint{ clientX, clientY };
		CUI_EXPECT_TRUE(::ClientToScreen(host.Handle, &wheelPoint));
		(void)::SendMessageW(
			host.Handle, WM_MOUSEWHEEL,
			MAKEWPARAM(0, WHEEL_DELTA),
			MAKELPARAM(wheelPoint.x, wheelPoint.y));
		CUI_EXPECT_TRUE(chart->GetZoomX() > oldZoom);
		CUI_EXPECT_TRUE(pointClick.Connected());
	});

	runner.Add("CalendarView owns transformed input beneath decorative template chrome", []
	{
		Window host;
		ConfigureTestControl(host, L"CalendarView transformed template input");
		SetDeclaredWindowGeometry(
			host, 0.0f, 0.0f, 360.0f, 260.0f);
		auto contentOwner = MakeTestControl<Canvas>();
		auto* content = static_cast<Canvas*>(
			host.SetVisualContent(std::move(contentOwner)));
		auto calendarOwner = MakeTestControl<CalendarView>(
			40.0f, 30.0f, 260.0f, 190.0f);
		auto* calendar = calendarOwner.get();
		SYSTEMTIME initial{};
		initial.wYear = 2026;
		initial.wMonth = 1;
		initial.wDay = 1;
		calendar->SetSelectedDate(initial);
		calendar->SetDisplayMonth(2027, 3);

		cui::drawing::Transform calendarTransform;
		cui::drawing::TransformOperation scale;
		scale.Kind = cui::drawing::TransformKind::Scale;
		scale.ScaleX = 1.03f;
		scale.ScaleY = 1.03f;
		cui::drawing::TransformOperation rotate;
		rotate.Kind = cui::drawing::TransformKind::Rotate;
		rotate.Angle = -3.5f;
		calendarTransform.Operations = { scale, rotate };
		calendar->SetRenderTransformOrigin(D2D1::Point2F(0.5f, 0.5f));
		calendar->SetRenderTransform(calendarTransform);

		// Mirror Generic.xaml's full-size decorative Grid/Border subtree.
		auto templateRoot = MakeTestControl<Grid>();
		auto* templateRootPointer = templateRoot.get();
		auto chromeOwner = MakeTestControl<Border>();
		auto* chrome = chromeOwner.get();
		cui::framework::TreeAccess::SetTemplatedParent(
			*templateRootPointer, calendar);
		cui::framework::TreeAccess::SetTemplatedParent(*chrome, calendar);
		templateRootPointer->AddOwned(std::move(chromeOwner));
		CUI_EXPECT_TRUE(cui::framework::TemplateAccess::SetTemplateRoot(
			*calendar, std::move(templateRoot)) == templateRootPointer);
		content->AddOwned(std::move(calendarOwner));
		host.UpdateLayout();

		CUI_EXPECT_FALSE(calendar->HitTestChildren());
		CUI_EXPECT_TRUE(chrome->GetActualSizeDip().width > 0.0f);
		CUI_EXPECT_TRUE(chrome->GetActualSizeDip().height > 0.0f);
		uint32_t cellId = 0;
		AccessibilityVirtualNode cell;
		CUI_EXPECT_TRUE(calendar->GetAccessibilityVirtualItemAt(
			2, 3, cellId));
		CUI_EXPECT_TRUE(calendar->TryGetAccessibilityVirtualNode(
			cellId, cell));
		const int localX = static_cast<int>(
			(cell.BoundsDip.left + cell.BoundsDip.right) * 0.5f);
		const int localY = static_cast<int>(
			(cell.BoundsDip.top + cell.BoundsDip.bottom) * 0.5f);
		SYSTEMTIME target{};
		bool inDisplayMonth = false;
		CUI_EXPECT_TRUE(calendar->HitTestDate(
			localX, localY, target, inDisplayMonth) >= 0);

		const auto rawTransform = calendar->GetLocalToRenderTransform();
		const auto renderPoint = D2D1::Matrix3x2F(
			rawTransform._11, rawTransform._12,
			rawTransform._21, rawTransform._22,
			rawTransform._31, rawTransform._32)
			.TransformPoint(D2D1::Point2F(
				static_cast<float>(localX), static_cast<float>(localY)));
		auto* hit = cui::framework::WindowAccess::HitTestControlAt(
			host, static_cast<int>(std::lround(renderPoint.x)),
			static_cast<int>(std::lround(renderPoint.y)));
		CUI_EXPECT_TRUE(hit == calendar);

		const auto clientPoint = host.ContentDipRectToClientPixels(
			D2D1::RectF(renderPoint.x, renderPoint.y,
				renderPoint.x + 1.0f, renderPoint.y + 1.0f));
		const LPARAM pointerPoint = MAKELPARAM(
			(clientPoint.left + clientPoint.right) / 2,
			(clientPoint.top + clientPoint.bottom) / 2);
		(void)::SendMessageW(
			host.Handle, WM_LBUTTONDOWN, MK_LBUTTON, pointerPoint);
		CUI_EXPECT_TRUE(host.GetMouseCaptured() == calendar);
		(void)::SendMessageW(host.Handle, WM_LBUTTONUP, 0, pointerPoint);
		CUI_EXPECT_TRUE(host.GetMouseCaptured() == nullptr);
		const auto selected = calendar->GetSelectedDate();
		CUI_EXPECT_EQ(static_cast<int>(target.wYear),
			static_cast<int>(selected.wYear));
		CUI_EXPECT_EQ(static_cast<int>(target.wMonth),
			static_cast<int>(selected.wMonth));
		CUI_EXPECT_EQ(static_cast<int>(target.wDay),
			static_cast<int>(selected.wDay));
	});

	runner.Add("Calendar exposes WPF date properties and Monday-first grid semantics", []
	{
		Calendar calendar;
		CUI_EXPECT_EQ(UIClass::UI_Calendar, calendar.Type());
		CUI_EXPECT_FALSE(calendar.HasSelectedDate());
		CUI_EXPECT_EQ(std::wstring(L"CUI.Calendar"),
			calendar.GetAutomationPeer().GetAutomationClassName());
		const auto* calendarType =
			CuiRuntime::XamlRuntimeSchema::FindBuiltInType(
				L"urn:cui", L"Calendar");
		const auto* datePickerType =
			CuiRuntime::XamlRuntimeSchema::FindBuiltInType(
				L"urn:cui", L"DatePicker");
		const auto* compatibilityType =
			CuiRuntime::XamlRuntimeSchema::FindBuiltInType(
				L"urn:cui", L"CalendarView");
		CUI_EXPECT_TRUE(calendarType != nullptr);
		CUI_EXPECT_TRUE(calendarType
			&& calendarType->NativeType == UIClass::UI_Calendar);
		CUI_EXPECT_TRUE(calendarType
			&& calendarType->IsDesignerToolboxType());
		CUI_EXPECT_TRUE(datePickerType != nullptr);
		CUI_EXPECT_TRUE(datePickerType
			&& datePickerType->NativeType == UIClass::UI_DatePicker);
		CUI_EXPECT_TRUE(datePickerType
			&& datePickerType->IsDesignerToolboxType());
		CUI_EXPECT_TRUE(compatibilityType != nullptr);
		CUI_EXPECT_TRUE(compatibilityType
			&& compatibilityType->NativeType == UIClass::UI_CalendarView);
		CUI_EXPECT_TRUE(compatibilityType
			&& !compatibilityType->IsDesignerToolboxType());
		CUI_EXPECT_EQ(UIClass::UI_CalendarView,
			GetUIClassBase(UIClass::UI_Calendar));
		for (const auto& [nativeType, propertyName] : std::to_array({
			std::pair{ UIClass::UI_Calendar, L"SelectedDate" },
			std::pair{ UIClass::UI_Calendar, L"DisplayDate" },
			std::pair{ UIClass::UI_Calendar, L"FirstDayOfWeek" },
			std::pair{ UIClass::UI_DatePicker, L"SelectedDate" },
			std::pair{ UIClass::UI_DatePicker, L"Text" },
			std::pair{ UIClass::UI_DatePicker, L"IsDropDownOpen" } }))
		{
			CUI_EXPECT_TRUE(
				CuiRuntime::XamlRuntimeSchema::FindNativeProperty(
					nativeType, propertyName) != nullptr);
		}

		// Keep this event assertion independent from the machine's current date.
		// August 15, 2026 is also a valid "today" for this evergreen test.
		SYSTEMTIME baseline{};
		baseline.wYear = 2026;
		baseline.wMonth = 8;
		baseline.wDay = 14;
		calendar.SetDisplayDate(baseline);
		int displayChanges = 0;
		auto displayChanged = calendar.DisplayDateChanged.Subscribe(
			[&](CalendarView* sender)
			{
				CUI_EXPECT_TRUE(sender == &calendar);
				++displayChanges;
			});
		SYSTEMTIME august{};
		august.wYear = 2026;
		august.wMonth = 8;
		august.wDay = 15;
		calendar.SetDisplayDate(august);
		calendar.SetFirstDayOfWeek(1);
		calendar.SetIsTodayHighlighted(false);
		CUI_EXPECT_EQ(1, displayChanges);
		CUI_EXPECT_EQ(1, calendar.GetFirstDayOfWeek());
		CUI_EXPECT_FALSE(calendar.GetIsTodayHighlighted());
		CUI_EXPECT_EQ(15,
			static_cast<int>(calendar.GetDisplayDate().wDay));

		std::vector<uint32_t> headers;
		calendar.GetAccessibilityVirtualColumnHeaders(headers);
		CUI_EXPECT_EQ(7ULL,
			static_cast<unsigned long long>(headers.size()));
		AccessibilityVirtualNode monday;
		CUI_EXPECT_TRUE(!headers.empty()
			&& calendar.TryGetAccessibilityVirtualNode(headers.front(), monday));
		CUI_EXPECT_EQ(std::wstring(L"Monday"), monday.Name);
		uint32_t leadingCell = 0;
		AccessibilityVirtualNode leadingDate;
		CUI_EXPECT_TRUE(calendar.GetAccessibilityVirtualItemAt(
			0, 0, leadingCell));
		CUI_EXPECT_TRUE(calendar.TryGetAccessibilityVirtualNode(
			leadingCell, leadingDate));
		CUI_EXPECT_EQ(std::wstring(L"2026-07-27"), leadingDate.Name);

		const auto* selectedMetadata =
			calendar.FindPropertyMetadata(L"SelectedDate");
		const auto* displayMetadata =
			calendar.FindPropertyMetadata(L"DisplayDate");
		CUI_EXPECT_TRUE(selectedMetadata != nullptr);
		CUI_EXPECT_TRUE(displayMetadata != nullptr);
		CUI_EXPECT_TRUE(selectedMetadata && HasDependencyPropertyFlag(
			selectedMetadata->Flags(),
			DependencyPropertyFlags::BindsTwoWayByDefault));
		CUI_EXPECT_TRUE(displayMetadata && HasDependencyPropertyFlag(
			displayMetadata->Flags(),
			DependencyPropertyFlags::BindsTwoWayByDefault));
		Calendar literalCalendar;
		CUI_EXPECT_TRUE(literalCalendar.TrySetPropertyValue(
			CalendarView::SelectedDateProperty(),
			BindingValue(std::wstring(L"2026-08-09"))));
		CUI_EXPECT_EQ(9,
			static_cast<int>(literalCalendar.GetSelectedDate().wDay));
		CUI_EXPECT_FALSE(literalCalendar.TrySetPropertyValue(
			CalendarView::SelectedDateProperty(),
			BindingValue(std::wstring(L"2026-02-30"))));
		DesignerStyleValueKind dateKind{};
		CUI_EXPECT_TRUE(DesignerPropertyCatalog::TryGetStyleValueKind(
			*selectedMetadata, dateKind));
		CUI_EXPECT_EQ(DesignerStyleValueKind::String, dateKind);
		DesignerStyleValue canonicalDate;
		CUI_EXPECT_TRUE(DesignerPropertyCatalog::NormalizeStyleValue(
			*selectedMetadata,
			DesignerStyleValue{
				DesignerStyleValueKind::String, L"2026-08-10" },
			canonicalDate));
		CUI_EXPECT_EQ(std::wstring(L"2026-08-10"), canonicalDate.Text);
		DatePicker literalPicker;
		CUI_EXPECT_TRUE(literalPicker.TrySetPropertyValue(
			DatePicker::DisplayDateProperty(),
			BindingValue(std::wstring(L"2027-02-14"))));
		CUI_EXPECT_EQ(14,
			static_cast<int>(literalPicker.GetDisplayDate().wDay));

		int selectionChanges = 0;
		auto selected = calendar.SelectedDatesChanged.Subscribe(
			[&](Control*, SelectionChangedEventArgs&) { ++selectionChanges; });
		SYSTEMTIME choice = august;
		choice.wDay = 8;
		calendar.SetSelectedDate(choice);
		CUI_EXPECT_TRUE(calendar.HasSelectedDate());
		CUI_EXPECT_EQ(8,
			static_cast<int>(calendar.GetSelectedDate().wDay));
		calendar.ClearSelectedDate();
		CUI_EXPECT_FALSE(calendar.HasSelectedDate());
		CUI_EXPECT_EQ(2, selectionChanges);
		CUI_EXPECT_TRUE(displayChanged.Connected());
		CUI_EXPECT_TRUE(selected.Connected());
	});

	runner.Add("DatePicker commits culture dates and preserves two-way date identity", []
	{
		DatePicker picker;
		CUI_EXPECT_EQ(UIClass::UI_DatePicker, picker.Type());
		CUI_EXPECT_FALSE(picker.HasSelectedDate());
		const auto* selectedMetadata =
			picker.FindPropertyMetadata(L"SelectedDate");
		const auto* openMetadata =
			picker.FindPropertyMetadata(L"IsDropDownOpen");
		CUI_EXPECT_TRUE(selectedMetadata != nullptr);
		CUI_EXPECT_TRUE(openMetadata != nullptr);
		CUI_EXPECT_TRUE(selectedMetadata && HasDependencyPropertyFlag(
			selectedMetadata->Flags(),
			DependencyPropertyFlags::BindsTwoWayByDefault));
		CUI_EXPECT_TRUE(openMetadata && HasDependencyPropertyFlag(
			openMetadata->Flags(),
			DependencyPropertyFlags::BindsTwoWayByDefault));

		int selectedChanges = 0;
		int validationErrors = 0;
		auto selected = picker.SelectedDateChanged.Subscribe(
			[&](DatePicker* sender, SelectionChangedEventArgs&)
			{
				CUI_EXPECT_TRUE(sender == &picker);
				++selectedChanges;
			});
		auto validation = picker.DateValidationError.Subscribe(
			[&](DatePicker* sender,
				DatePickerDateValidationErrorEventArgs& args)
			{
				CUI_EXPECT_TRUE(sender == &picker);
				CUI_EXPECT_EQ(std::wstring(L"not-a-date"), args.Text);
				++validationErrors;
			});
		picker.SetText(L"2026-08-08");
		CUI_EXPECT_TRUE(picker.CommitText());
		CUI_EXPECT_TRUE(picker.HasSelectedDate());
		CUI_EXPECT_EQ(2026,
			static_cast<int>(picker.GetSelectedDate().wYear));
		CUI_EXPECT_EQ(8,
			static_cast<int>(picker.GetSelectedDate().wMonth));
		CUI_EXPECT_EQ(8,
			static_cast<int>(picker.GetSelectedDate().wDay));
		CUI_EXPECT_TRUE(!picker.GetText().empty());
		CUI_EXPECT_EQ(1, selectedChanges);

		picker.SetSelectedDateFormat(DatePickerFormat::Short);
		const auto validText = picker.GetText();
		CUI_EXPECT_TRUE(!validText.empty());
		picker.SetText(L"not-a-date");
		CUI_EXPECT_FALSE(picker.CommitText());
		CUI_EXPECT_EQ(1, validationErrors);
		CUI_EXPECT_EQ(validText, picker.GetText());
		CUI_EXPECT_EQ(8,
			static_cast<int>(picker.GetSelectedDate().wDay));

		ObservableObject source;
		source.SetValue(L"Date", picker.GetSelectedDate());
		CUI_EXPECT_TRUE(picker.DataBindings.Add(
			L"SelectedDate", source, L"Date", BindingMode::TwoWay) != nullptr);
		picker.SetText(L"2026-08-18");
		CUI_EXPECT_TRUE(picker.CommitText());
		CUI_EXPECT_EQ(18, static_cast<int>(
			source.GetValue<SYSTEMTIME>(L"Date").wDay));
		CUI_EXPECT_TRUE(picker.GetAutomationPeer().SupportsPattern(
			AutomationPattern::Value));
		CUI_EXPECT_TRUE(picker.GetAutomationPeer().SupportsPattern(
			AutomationPattern::ExpandCollapse));
		CUI_EXPECT_TRUE(selected.Connected());
		CUI_EXPECT_TRUE(validation.Connected());
	});

	runner.Add("DatePicker template parts own one popup Calendar interaction surface", []
	{
		Window host;
		ConfigureTestControl(host, L"DatePicker popup template");
		SetDeclaredWindowGeometry(host, 0.0f, 0.0f, 420.0f, 360.0f);
		auto contentOwner = MakeTestControl<Canvas>();
		auto* content = static_cast<Canvas*>(
			host.SetVisualContent(std::move(contentOwner)));
		auto pickerOwner = MakeTestControl<DatePicker>(
			20.0f, 20.0f, 200.0f, 32.0f);
		auto* picker = pickerOwner.get();

		auto rootOwner = MakeTestControl<Grid>();
		auto* root = rootOwner.get();
		auto textOwner = MakeTestControl<TextBox>();
		auto* text = textOwner.get();
		auto buttonOwner = MakeTestControl<Button>();
		auto* button = buttonOwner.get();
		auto popupOwner = MakeTestControl<Popup>();
		auto* popup = popupOwner.get();
		for (auto* part : std::to_array<Control*>({ root, text, button, popup }))
			cui::framework::XamlAccess::SetTemplatedParent(*part, picker);
		root->AddOwned(std::move(textOwner));
		root->AddOwned(std::move(buttonOwner));
		root->AddOwned(std::move(popupOwner));
		CUI_EXPECT_TRUE(cui::framework::TemplateAccess::RegisterTemplatePart(
			*picker, MakeTemplatePartToken(L"PART_TextBox"), text));
		CUI_EXPECT_TRUE(cui::framework::TemplateAccess::RegisterTemplatePart(
			*picker, MakeTemplatePartToken(L"PART_Button"), button));
		CUI_EXPECT_TRUE(cui::framework::TemplateAccess::RegisterTemplatePart(
			*picker, MakeTemplatePartToken(L"PART_Popup"), popup));
		CUI_EXPECT_TRUE(cui::framework::TemplateAccess::SetTemplateRoot(
			*picker, std::move(rootOwner)) == root);
		content->AddOwned(std::move(pickerOwner));
		host.UpdateLayout();

		auto* calendar = picker->GetCalendar();
		CUI_EXPECT_TRUE(calendar != nullptr);
		CUI_EXPECT_TRUE(popup->GetChild() == calendar);
		CUI_EXPECT_TRUE(calendar && calendar->GetVisualParent() == popup);
		CUI_EXPECT_TRUE(popup->GetPlacementTarget() == picker);
		CUI_EXPECT_EQ(PlacementMode::Bottom, popup->GetPlacement());
		CUI_EXPECT_FALSE(popup->GetStaysOpen());

		int opened = 0;
		int closed = 0;
		auto openedConnection = picker->CalendarOpened.Subscribe(
			[&](DatePicker*) { ++opened; });
		auto closedConnection = picker->CalendarClosed.Subscribe(
			[&](DatePicker*) { ++closed; });
		picker->SetText(L"2027-03-11");
		CUI_EXPECT_TRUE(button->Invoke());
		CUI_EXPECT_TRUE(picker->GetIsDropDownOpen());
		CUI_EXPECT_TRUE(popup->GetIsOpen());
		CUI_EXPECT_EQ(1, opened);
		CUI_EXPECT_EQ(11,
			static_cast<int>(picker->GetSelectedDate().wDay));
		int calendarSelectionChanges = 0;
		auto calendarSelectionConnection =
			calendar->SelectedDatesChanged.Subscribe(
				[&](Control*, SelectionChangedEventArgs&)
				{ ++calendarSelectionChanges; });
		CUI_EXPECT_EQ(11,
			static_cast<int>(calendar->GetSelectedDate().wDay));

		SYSTEMTIME selectedDate{};
		selectedDate.wYear = 2027;
		selectedDate.wMonth = 3;
		selectedDate.wDay = 22;
		calendar->SetSelectedDate(selectedDate);
		CUI_EXPECT_EQ(22,
			static_cast<int>(calendar->GetSelectedDate().wDay));
		CUI_EXPECT_EQ(1, calendarSelectionChanges);
		CUI_EXPECT_EQ(22,
			static_cast<int>(picker->GetSelectedDate().wDay));
		MouseEventArgs mouseUp(
			MouseButton::Left, MouseButtonState::Released, 1, 20, 20, 0);
		cui::framework::RoutedEventAccess::InvokeHandlers(
			calendar->OnMouseUp, calendar, mouseUp);
		CUI_EXPECT_FALSE(picker->GetIsDropDownOpen());
		CUI_EXPECT_FALSE(popup->GetIsOpen());
		CUI_EXPECT_EQ(1, closed);

		CUI_EXPECT_TRUE(button->Invoke());
		CUI_EXPECT_TRUE(picker->GetIsDropDownOpen());
		SYSTEMTIME transient = selectedDate;
		transient.wDay = 25;
		calendar->SetSelectedDate(transient);
		KeyEventArgs escape(Key::Escape);
		cui::framework::RoutedEventAccess::InvokeHandlers(
			calendar->OnKeyDown, calendar, escape);
		CUI_EXPECT_FALSE(picker->GetIsDropDownOpen());
		CUI_EXPECT_EQ(22,
			static_cast<int>(picker->GetSelectedDate().wDay));

		CUI_EXPECT_TRUE(cui::framework::TemplateAccess::SetTemplateRoot(
			*picker, {}) == nullptr);
		CUI_EXPECT_TRUE(picker->GetCalendar() == calendar);
		CUI_EXPECT_TRUE(calendar->GetVisualParent() == nullptr);
		CUI_EXPECT_TRUE(openedConnection.Connected());
		CUI_EXPECT_TRUE(closedConnection.Connected());
		CUI_EXPECT_TRUE(calendarSelectionConnection.Connected());
	});

	runner.Add("RelativePanel attached constraints round-trip and materialize dynamically", []
	{
		const std::string xaml = R"XAML(<Window xmlns="urn:cui"
  xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
  x:Name="RelativeWindow" Width="640" Height="480">
  <RelativePanel x:Name="layout" Width="600" Height="400">
    <Button x:Name="anchor" Content="Anchor"
            RelativePanel.AlignLeftWithPanel="true"
            RelativePanel.AlignTopWithPanel="true" />
    <Button x:Name="center" Content="Center"
            RelativePanel.CenterHorizontal="true"
            RelativePanel.CenterVertical="true"
            RelativePanel.AlignRightWithPanel="false" />
    <TextBlock x:Name="floating" Text="Floating"
           RelativePanel.AlignRightWithPanel="true"
           RelativePanel.AlignBottomWithPanel="true"
           RelativePanel.Above="anchor"
           RelativePanel.Below="center"
           RelativePanel.LeftOf="anchor"
           RelativePanel.RightOf="center"
           RelativePanel.AlignLeftWith="anchor"
           RelativePanel.AlignRightWith="center"
           RelativePanel.AlignTopWith="anchor"
           RelativePanel.AlignBottomWith="center" />
  </RelativePanel>
</Window>)XAML";

		DesignerModel::DesignDocument document;
		std::wstring error;
		CUI_EXPECT_TRUE(DesignerModel::XamlDocumentParser::FromXaml(
			xaml, document, &error));
		CUI_EXPECT_TRUE(error.empty());
		CUI_EXPECT_EQ(4ULL, document.Nodes.size());
		const auto& authoredCenterConstraints =
			*document.Nodes[2].Structure.RelativePanel;
		CUI_EXPECT_EQ(std::optional<bool>(true),
			authoredCenterConstraints.CenterHorizontal);
		CUI_EXPECT_EQ(std::optional<bool>(true),
			authoredCenterConstraints.CenterVertical);
		CUI_EXPECT_EQ(std::optional<bool>(false),
			authoredCenterConstraints.AlignRightWithPanel);
		const auto& authoredFloatingConstraints =
			*document.Nodes[3].Structure.RelativePanel;
		CUI_EXPECT_EQ(std::optional<std::wstring>(L"anchor"),
			authoredFloatingConstraints.Above);
		CUI_EXPECT_EQ(std::optional<std::wstring>(L"center"),
			authoredFloatingConstraints.AlignBottomWith);

		const auto canonical =
			DesignerModel::XamlDocumentSerializer::ToXaml(document);
		for (const auto marker : {
			"RelativePanel.CenterHorizontal=\"true\"",
			"RelativePanel.CenterVertical=\"true\"",
			"RelativePanel.AlignRightWithPanel=\"false\"",
			"RelativePanel.Above=\"anchor\"",
			"RelativePanel.Below=\"center\"",
			"RelativePanel.LeftOf=\"anchor\"",
			"RelativePanel.RightOf=\"center\"",
			"RelativePanel.AlignLeftWith=\"anchor\"",
			"RelativePanel.AlignRightWith=\"center\"",
			"RelativePanel.AlignTopWith=\"anchor\"",
			"RelativePanel.AlignBottomWith=\"center\"" })
			CUI_EXPECT_TRUE(canonical.find(marker) != std::string::npos);
		DesignerModel::DesignDocument roundTrip;
		CUI_EXPECT_TRUE(DesignerModel::XamlDocumentParser::FromXaml(
			canonical, roundTrip, &error));
		CUI_EXPECT_EQ(document, roundTrip);
		const auto snapshot =
			DesignerModel::DesignDocumentSerializer::ToXml(document);
		DesignerModel::DesignDocument snapshotRoundTrip;
		CUI_EXPECT_TRUE(DesignerModel::DesignDocumentSerializer::FromXml(
			snapshot, snapshotRoundTrip, &error));
		CUI_EXPECT_EQ(document, snapshotRoundTrip);

		CuiRuntime::XamlObjectTree tree;
		CUI_EXPECT_TRUE(CuiRuntime::XamlObjectMaterializer::Materialize(
			document, tree, &error));
		CUI_EXPECT_TRUE(tree.ContentRoot != nullptr);
		auto* panel = dynamic_cast<RelativePanel*>(
			tree.ContentRoot.get());
		auto* anchor = FindMaterializedControlByName(tree, L"anchor");
		auto* center = FindMaterializedControlByName(tree, L"center");
		auto* floating = FindMaterializedControlByName(tree, L"floating");
		CUI_EXPECT_TRUE(panel != nullptr && anchor != nullptr
			&& center != nullptr && floating != nullptr);
		const auto* anchorConstraints = panel
			? panel->GetConstraints(anchor) : nullptr;
		CUI_EXPECT_TRUE(anchorConstraints
			&& anchorConstraints->AlignLeftWithPanel
			&& anchorConstraints->AlignTopWithPanel);
		const auto* centerConstraints = panel
			? panel->GetConstraints(center) : nullptr;
		CUI_EXPECT_TRUE(centerConstraints
			&& centerConstraints->CenterHorizontal
			&& centerConstraints->CenterVertical);
		CUI_EXPECT_FALSE(centerConstraints
			&& centerConstraints->AlignRightWithPanel);
		const auto* floatingConstraints = panel
			? panel->GetConstraints(floating) : nullptr;
		CUI_EXPECT_TRUE(floatingConstraints != nullptr);
		if (floatingConstraints)
		{
			CUI_EXPECT_TRUE(floatingConstraints->AlignRightWithPanel);
			CUI_EXPECT_TRUE(floatingConstraints->AlignBottomWithPanel);
			CUI_EXPECT_TRUE(floatingConstraints->Above == anchor);
			CUI_EXPECT_TRUE(floatingConstraints->Below == center);
			CUI_EXPECT_TRUE(floatingConstraints->LeftOf == anchor);
			CUI_EXPECT_TRUE(floatingConstraints->RightOf == center);
			CUI_EXPECT_TRUE(floatingConstraints->AlignLeftWith == anchor);
			CUI_EXPECT_TRUE(floatingConstraints->AlignRightWith == center);
			CUI_EXPECT_TRUE(floatingConstraints->AlignTopWith == anchor);
			CUI_EXPECT_TRUE(floatingConstraints->AlignBottomWith == center);
		}

		DesignerModel::RuntimeDocument runtime;
		CUI_EXPECT_TRUE(DesignerModel::RuntimeDocumentLoader::Load(
			document, runtime, {}, &error));
		auto changedXaml = canonical;
		const auto centerEnabled = changedXaml.find(
			"RelativePanel.CenterHorizontal=\"true\"");
		CUI_EXPECT_TRUE(centerEnabled != std::string::npos);
		if (centerEnabled != std::string::npos)
			changedXaml.replace(centerEnabled,
				std::string("RelativePanel.CenterHorizontal=\"true\"").size(),
				"RelativePanel.CenterHorizontal=\"false\"");
		DesignerModel::DesignDocument changed;
		CUI_EXPECT_TRUE(DesignerModel::XamlDocumentParser::FromXaml(
			changedXaml, changed, &error));
		DesignerModel::RuntimeDocumentReloadMode reloadMode{};
		CUI_EXPECT_TRUE(DesignerModel::RuntimeDocumentLoader::Reload(
			changed, runtime, {}, &reloadMode, &error));
		auto* reloadedPanel = dynamic_cast<RelativePanel*>(
			runtime.FindControlByName(L"layout"));
		auto* reloadedCenter = runtime.FindControlByName(L"center");
		const auto* reloadedConstraints = reloadedPanel
			? reloadedPanel->GetConstraints(reloadedCenter) : nullptr;
		CUI_EXPECT_TRUE(reloadedConstraints != nullptr);
		CUI_EXPECT_FALSE(reloadedConstraints
			&& reloadedConstraints->CenterHorizontal);

		auto invalidBoolean = xaml;
		const auto booleanValue = invalidBoolean.find(
			"RelativePanel.CenterVertical=\"true\"");
		if (booleanValue != std::string::npos)
			invalidBoolean.replace(booleanValue,
				std::string("RelativePanel.CenterVertical=\"true\"").size(),
				"RelativePanel.CenterVertical=\"sometimes\"");
		auto unchanged = document;
		DesignerModel::XamlDocumentDiagnostic diagnostic;
		CUI_EXPECT_FALSE(DesignerModel::XamlDocumentParser::FromXaml(
			invalidBoolean, unchanged, &error, &diagnostic));
		CUI_EXPECT_EQ(document, unchanged);
		CUI_EXPECT_TRUE(error.find(L"布尔") != std::wstring::npos);
		CUI_EXPECT_TRUE(diagnostic.HasSourceOffset());

		auto missingTarget = xaml;
		const auto targetValue = missingTarget.find(
			"RelativePanel.Below=\"center\"");
		if (targetValue != std::string::npos)
			missingTarget.replace(targetValue,
				std::string("RelativePanel.Below=\"center\"").size(),
				"RelativePanel.Below=\"missing\"");
		unchanged = document;
		CUI_EXPECT_FALSE(DesignerModel::XamlDocumentParser::FromXaml(
			missingTarget, unchanged, &error));
		CUI_EXPECT_EQ(document, unchanged);
		CUI_EXPECT_TRUE(error.find(L"不存在") != std::wstring::npos);

		const std::string wrongParent = R"XAML(<Window xmlns="urn:cui"
  xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" x:Name="WrongParent">
  <Canvas x:Name="plain">
    <Button x:Name="child"
            RelativePanel.CenterHorizontal="true" />
  </Canvas>
</Window>)XAML";
		unchanged = document;
		CUI_EXPECT_FALSE(DesignerModel::XamlDocumentParser::FromXaml(
			wrongParent, unchanged, &error));
		CUI_EXPECT_EQ(document, unchanged);
		CUI_EXPECT_TRUE(error.find(L"直接子控件") != std::wstring::npos);
	});

