    runner.Add("Designer binding validation uses target metadata capabilities", []
	{
		Control target;
		DesignerDataBinding binding{
			L"Profile.Width", BindingMode::OneWay,
			DataSourceUpdateMode::OnPropertyChanged };
		const DependencyPropertyMetadata* metadata = nullptr;
		std::wstring error;
		CUI_EXPECT_TRUE(DesignerBindingUtils::Validate(
			target, L"Width", binding, &metadata, &error));
		CUI_EXPECT_TRUE(metadata != nullptr);
		CUI_EXPECT_EQ(std::wstring(L"Width"), metadata->Name());
		CUI_EXPECT_TRUE(error.empty());

		binding.Mode = BindingMode::TwoWay;
		CUI_EXPECT_TRUE(DesignerBindingUtils::Validate(
			target, L"Width", binding, nullptr, &error));
		CUI_EXPECT_TRUE(error.empty());

		binding.UpdateMode = DataSourceUpdateMode::Never;
		CUI_EXPECT_TRUE(DesignerBindingUtils::Validate(
			target, L"Width", binding, nullptr, &error));

		binding.SourceProperty = L"Profile..Width";
		CUI_EXPECT_FALSE(DesignerBindingUtils::Validate(
			target, L"Width", binding, nullptr, &error));
		CUI_EXPECT_TRUE(error.find(L"源路径") != std::wstring::npos);

		binding = DesignerDataBinding{
			L"Profile.Name", BindingMode::OneWay,
			DataSourceUpdateMode::OnPropertyChanged, L"StringIsNotEmpty" };
		CheckBox toggleTarget;
		CUI_EXPECT_TRUE(DesignerBindingUtils::Validate(
			toggleTarget, L"IsChecked", binding, &metadata, &error));
		CUI_EXPECT_EQ(
			BindingValueKind::NullableBool, metadata->ValueKind());
		const auto toggleProperties =
			DesignerPropertyCatalog::GetStyleProperties(toggleTarget);
		const auto* checkedProperty = DesignerPropertyCatalog::Find(
			toggleProperties, L"IsChecked");
		CUI_EXPECT_TRUE(checkedProperty != nullptr);
		CUI_EXPECT_EQ(
			DependencyPropertyEditorKind::Choice,
			checkedProperty->Editor);
		CUI_EXPECT_EQ(3ULL, checkedProperty->Choices.size());

		binding.Mode = BindingMode::TwoWay;
		CUI_EXPECT_FALSE(DesignerBindingUtils::Validate(
			toggleTarget, L"IsChecked", binding, nullptr, &error));
		CUI_EXPECT_TRUE(error.find(L"ConvertBack") != std::wstring::npos);

		binding.Mode = BindingMode::OneWay;
		binding.Converter = L"StringTrim";
		CUI_EXPECT_FALSE(DesignerBindingUtils::Validate(
			toggleTarget, L"IsChecked", binding, nullptr, &error));
		CUI_EXPECT_TRUE(error.find(L"类型") != std::wstring::npos);

		binding.Converter = L"Application.CustomConverter";
		CUI_EXPECT_TRUE(DesignerBindingUtils::Validate(
			toggleTarget, L"IsChecked", binding, nullptr, &error));
	});

	runner.Add("Calendar binding metadata discovery returns effective properties", []
    {
		CalendarView picker;
        const auto properties = DependencyPropertyRegistry::GetProperties(picker);
        CUI_EXPECT_TRUE(!properties.empty());

        auto findProperty = [&](const wchar_t* name)
        {
            auto it = std::find_if(properties.begin(), properties.end(),
                [name](const DependencyPropertyMetadata* property)
                {
                    return property->Name() == name;
                });
            return it == properties.end() ? nullptr : *it;
        };

		const auto* text = findProperty(L"Text");
		const auto* value = findProperty(L"SelectedDate");
		const auto* validationHasError = findProperty(L"Validation.HasError");
		const auto* validationErrors = findProperty(L"Validation.Errors");
		const auto* accessibleDescription = findProperty(L"AutomationProperties.FullDescription");
		CUI_EXPECT_TRUE(text == nullptr);
		CUI_EXPECT_TRUE(value != nullptr);
		CUI_EXPECT_TRUE(validationHasError != nullptr);
		CUI_EXPECT_TRUE(validationErrors != nullptr);
		CUI_EXPECT_TRUE(accessibleDescription != nullptr);
		CUI_EXPECT_TRUE(value->CanRead());
        CUI_EXPECT_TRUE(value->CanWrite());
		CUI_EXPECT_TRUE(value->CanObserve());
		CUI_EXPECT_TRUE(validationHasError->CanRead());
		CUI_EXPECT_FALSE(validationHasError->CanWrite());
		CUI_EXPECT_TRUE(validationHasError->CanObserve());
		CUI_EXPECT_TRUE(validationErrors->CanRead());
		CUI_EXPECT_FALSE(validationErrors->CanWrite());
		CUI_EXPECT_TRUE(validationErrors->CanObserve());
		CUI_EXPECT_EQ(BindingValueKind::String,
			accessibleDescription->ValueKind());

        for (size_t i = 1; i < properties.size(); ++i)
        {
            CUI_EXPECT_TRUE(_wcsicmp(
                properties[i - 1]->Name().c_str(),
                properties[i]->Name().c_str()) < 0);
        }
    });

