		auto* logicalHost = AddTestVisual<Panel>(*root);
		auto* leaf = AddTestVisual<Control>(*visualHost, 0, 0, 70, 28);
		cui::framework::XamlAccess::SetLogicalParent(*leaf, logicalHost);
		CUI_EXPECT_TRUE(leaf->GetRoutedParent() == visualHost);
