		const ControlWeakReference movingLifetime(moving);
		moving->Owner = root;
		moving->Detached = &detached;
		CUI_EXPECT_TRUE(root->AddOwned(std::move(movingOwner)) == moving);
		auto* sibling = AddTestVisual<Panel>(*root);
		std::unique_ptr<Control> windowContent = std::move(rootOwner);
