		CUI_EXPECT_TRUE(moving->GetLogicalParent() == nullptr);
		CUI_EXPECT_TRUE(moving->GetPresentationWindow() == nullptr);
		CUI_EXPECT_TRUE(sibling->GetPresentationWindow() == &window);
