		auto* moving = movingOwner.get();
		moving->PreviousOwner = previousOwner;
		moving->NextOwner = nextOwner;
		CUI_EXPECT_TRUE(previousOwner->AddOwned(std::move(movingOwner)) == moving);
		window.SetVisualContent(std::move(root));
		CUI_EXPECT_TRUE(moving->DidMove);
		CUI_EXPECT_FALSE(previousOwner->ContainsControl(moving));
		CUI_EXPECT_TRUE(nextOwner->ContainsControl(moving));
