	runner.Add("Observed explicit command target expiration never falls back to focus", []
	{
		Window window; ConfigureTestControl(window, L"Explicit target lifetime");
		SetDeclaredWindowGeometry(window, 0.0f, 0.0f, 320.0f, 120.0f);
		std::unique_ptr<Control> rootOwner = MakeTestControl<Panel>();
		auto* root = dynamic_cast<Panel*>(rootOwner.get());
		auto* source = AddTestVisual<Button>(*root, L"Source", 0, 0);
		auto* explicitTarget = AddTestVisual<Panel>(*root);
		auto* focusedFallback = AddTestVisual<Button>(*root, L"Fallback", 120, 0);
		focusedFallback->Focusable = true;
		CUI_EXPECT_TRUE(window.TrySetVisualContent(rootOwner));
		window.SetKeyboardFocus(focusedFallback, false);

		const RoutedCommand command(L"Core.ExplicitTargetLifetime");
		CommandBinding binding;
		binding.Command = command;
		binding.CanExecute = [](
			Control*, CanExecuteRoutedEventArgs& args)
		{
			args.CanExecute = true;
		};
		auto targetBinding = explicitTarget->AddCommandBinding(binding);
		auto fallbackBinding = focusedFallback->AddCommandBinding(std::move(binding));
		std::vector<RoutedCommandCanExecuteResult> observed;
		auto observer = RoutedCommandManager::ObserveCanExecute(
			*source,
			RoutedCommandSourceQuery{
				command, {}, ControlWeakReference(explicitTarget) },
			[&](Control&, const RoutedCommandCanExecuteResult& result)
			{
				observed.push_back(result);
				source->SetCommandCanExecuteState(result.CanExecute);
			});
		CUI_EXPECT_TRUE(observer.Connected());
		CUI_EXPECT_TRUE(!observed.empty() && observed.back().CanExecute);
		CUI_EXPECT_TRUE(observed.back().Target == explicitTarget);
		CUI_EXPECT_TRUE(root->DeleteVisualChild(explicitTarget));
		cui::PumpUIThreadCallbacks();
		CUI_EXPECT_TRUE(!observed.empty());
		CUI_EXPECT_FALSE(observed.back().CanExecute);
		CUI_EXPECT_TRUE(observed.back().Target == nullptr);
		CUI_EXPECT_FALSE(source->IsEffectivelyEnabled());
		CUI_EXPECT_TRUE(window.GetKeyboardFocusedElement() == focusedFallback);
	});

