	runner.Add("RoutedCommand instance bindings own lifetime and freeze one execute route", []
	{
		Panel originalRoot;
		Panel replacementRoot;
		auto* middle = AddTestVisual<Panel>(originalRoot);
		auto* source = middle ? AddTestVisual<Button>(*middle, L"Route source", 0, 0) : nullptr;
		CUI_EXPECT_TRUE(middle && source);
		if (!middle || !source) return;

		const RoutedCommand command(L"Core.RouteSnapshot");
		int canCount = 0;
		int executedCount = 0;
		std::uint64_t observedTransaction = 0;
		std::uint64_t observedRoute = 0;
		CommandBinding binding;
		binding.Command = command;
		binding.CanExecute = [&](Control* sender, CanExecuteRoutedEventArgs& args)
		{
			++canCount;
			CUI_EXPECT_TRUE(sender == &originalRoot);
			CUI_EXPECT_TRUE(args.OriginalSource == source);
			observedTransaction = args.CommandTransactionId;
			observedRoute = args.CommandRouteId;
			args.CanExecute = true;
			auto moved = originalRoot.DetachVisualChild(middle);
			CUI_EXPECT_TRUE(moved.get() == middle);
			CUI_EXPECT_TRUE(replacementRoot.AddOwned(std::move(moved)) == middle);
		};
		binding.Executed = [&](Control* sender, ExecutedRoutedEventArgs& args)
		{
			++executedCount;
			CUI_EXPECT_TRUE(sender == &originalRoot);
			CUI_EXPECT_TRUE(args.OriginalSource == source);
			CUI_EXPECT_EQ(observedTransaction, args.CommandTransactionId);
			CUI_EXPECT_EQ(observedRoute, args.CommandRouteId);
		};
		auto lifetime = originalRoot.AddCommandBinding(std::move(binding));
		CUI_EXPECT_TRUE(lifetime.Connected());

		const auto result = RoutedCommandManager::ExecuteCommand(
			command, *source, std::wstring(L"payload"));
		CUI_EXPECT_TRUE(result.Query.CanExecute);
		CUI_EXPECT_TRUE(result.Query.Handled);
		CUI_EXPECT_TRUE(result.Executed);
		CUI_EXPECT_TRUE(result.Handled);
		CUI_EXPECT_EQ(3ULL,
			static_cast<unsigned long long>(result.Query.RouteDepth));
		CUI_EXPECT_EQ(result.TransactionId, result.Query.TransactionId);
		CUI_EXPECT_EQ(result.RouteId, result.Query.RouteId);
		CUI_EXPECT_EQ(observedTransaction, result.TransactionId);
		CUI_EXPECT_EQ(observedRoute, result.RouteId);
		CUI_EXPECT_EQ(1, canCount);
		CUI_EXPECT_EQ(1, executedCount);
		CUI_EXPECT_TRUE(source->GetRoutedParent() == middle);
		CUI_EXPECT_TRUE(middle->GetRoutedParent() == &replacementRoot);

		lifetime.Disconnect();
		CUI_EXPECT_FALSE(RoutedCommandManager::QueryCanExecute(
			command, *source).CanExecute);
	});

