		CUI_EXPECT_TRUE(context->GetPresentationWindow() == &window);
		CUI_EXPECT_TRUE(contextBranch->GetPresentationWindow() == &window);
		CUI_EXPECT_TRUE(contextLeaf->GetPresentationWindow() == &window);
		CUI_EXPECT_TRUE(menu->GetPresentationWindow() == &window);
		CUI_EXPECT_TRUE(menuBranch->GetPresentationWindow() == &window);
		CUI_EXPECT_TRUE(menuLeaf->GetPresentationWindow() == &window);
		CUI_EXPECT_TRUE(contextLeaf->IsEffectivelyEnabled());
