	runner.Add("TextCompositionManager tombstones canceled native IME sessions until a real session reset", []
	{
		Window form; ConfigureTestControl(form, L"Stale native IME session");
		SetDeclaredWindowGeometry(form, 0.0f, 0.0f, 420.0f, 180.0f);
		auto contentOwner = MakeTestControl<Panel>();
		auto* content = static_cast<Panel*>(
			form.SetVisualContent(std::move(contentOwner)));
		auto* first = AddTestVisual<TextBox>(*content, L"", 0, 0, 180, 28);
		auto* second = AddTestVisual<TextBox>(*content, L"", 0, 40, 180, 28);
		first->Focusable = true;
		second->Focusable = true;
		form.SetKeyboardFocus(first, false);

		auto& manager = cui::framework::WindowAccess::TextComposition(form);
		const auto nativeStart = manager.ProcessWindowMessage(
			WM_IME_STARTCOMPOSITION, 0, 0);
		CUI_EXPECT_TRUE(nativeStart.Recognized);
		CUI_EXPECT_TRUE(manager.Snapshot().IsComposing);
		CUI_EXPECT_TRUE(manager.Snapshot().Source == first);
		CUI_EXPECT_EQ(TextCompositionInputKind::Ime,
			manager.Snapshot().InputKind);
		CUI_EXPECT_TRUE(manager.UpdateComposition(L"old-preedit", 4));
		manager.CancelComposition(TextCompositionCancelReason::FocusChanged);
		const auto canceled = manager.Snapshot();
		CUI_EXPECT_FALSE(canceled.IsComposing);
		CUI_EXPECT_EQ(TextCompositionCancelReason::FocusChanged,
			canceled.CancelReason);
		form.SetKeyboardFocus(second, false);
		CUI_EXPECT_TRUE(form.GetKeyboardFocusedElement() == second);
		const auto staleNativeCancellation = manager.ProcessWindowMessage(
			WM_IME_COMPOSITION, 0, 0);
		CUI_EXPECT_TRUE(staleNativeCancellation.Recognized);
		CUI_EXPECT_FALSE(
			staleNativeCancellation.CallDefaultWindowProcedure);
		CUI_EXPECT_FALSE(staleNativeCancellation.TextApplied);
		CUI_EXPECT_EQ(TextCompositionStage::Canceled,
			manager.Snapshot().Stage);

		const auto beforeStale = manager.Statistics();
		CUI_EXPECT_EQ(1ULL, beforeStale.NativeImeSessionsTombstoned);
		bool staleSuppressed = false;
		const bool staleApplied =
			TextCompositionManagerTestAccess::ProcessNativeCompositionPayload(
				manager, true, L"Z", true, L"ghost-preedit",
				staleSuppressed, 3);
		CUI_EXPECT_TRUE(staleSuppressed);
		CUI_EXPECT_FALSE(staleApplied);
		CUI_EXPECT_EQ(std::wstring{}, first->Text);
		CUI_EXPECT_EQ(std::wstring{}, second->Text);
		const auto afterStale = manager.Snapshot();
		CUI_EXPECT_FALSE(afterStale.IsComposing);
		CUI_EXPECT_EQ(canceled.CompositionId, afterStale.CompositionId);
		CUI_EXPECT_EQ(TextCompositionStage::Canceled, afterStale.Stage);
		CUI_EXPECT_EQ(TextCompositionCancelReason::FocusChanged,
			afterStale.CancelReason);
		const auto staleStatistics = manager.Statistics();
		CUI_EXPECT_EQ(beforeStale.StaleImeResultsDiscarded + 1,
			staleStatistics.StaleImeResultsDiscarded);
		CUI_EXPECT_EQ(
			beforeStale.StaleImeCompositionUpdatesDiscarded + 1,
			staleStatistics.StaleImeCompositionUpdatesDiscarded);

		const auto staleEcho = manager.ProcessWindowMessage(
			WM_CHAR, static_cast<WPARAM>(L'Z'), 0);
		CUI_EXPECT_TRUE(staleEcho.Recognized);
		CUI_EXPECT_FALSE(staleEcho.TextApplied);
		CUI_EXPECT_EQ(std::wstring{}, second->Text);
		CUI_EXPECT_EQ(staleStatistics.ImeEchoesSuppressed + 1,
			manager.Statistics().ImeEchoesSuppressed);
		const auto ordinaryCharacter = manager.ProcessWindowMessage(
			WM_CHAR, static_cast<WPARAM>(L'x'), 0);
		CUI_EXPECT_TRUE(ordinaryCharacter.TextApplied);
		CUI_EXPECT_EQ(std::wstring(L"x"), second->Text);

		CUI_EXPECT_TRUE(manager.StartComposition(
			second, TextCompositionInputKind::Programmatic));
		CUI_EXPECT_TRUE(manager.UpdateComposition(L"programmatic", 6));
		const auto programmatic = manager.Snapshot();
		CUI_EXPECT_EQ(TextCompositionInputKind::Programmatic,
			programmatic.InputKind);
		bool programmaticStaleSuppressed = false;
		CUI_EXPECT_FALSE(
			TextCompositionManagerTestAccess::ProcessNativeCompositionPayload(
				manager, false, {}, true, L"must-not-restart",
				programmaticStaleSuppressed, 5));
		CUI_EXPECT_TRUE(programmaticStaleSuppressed);
		const auto programmaticAfterStale = manager.Snapshot();
		CUI_EXPECT_TRUE(programmaticAfterStale.IsComposing);
		CUI_EXPECT_EQ(programmatic.CompositionId,
			programmaticAfterStale.CompositionId);
		CUI_EXPECT_EQ(TextCompositionInputKind::Programmatic,
			programmaticAfterStale.InputKind);
		CUI_EXPECT_EQ(std::wstring(L"programmatic"),
			programmaticAfterStale.CompositionText);
		const auto staleEnd = manager.ProcessWindowMessage(
			WM_IME_ENDCOMPOSITION, 0, 0);
		CUI_EXPECT_TRUE(staleEnd.Recognized);
		const auto programmaticAfterEnd = manager.Snapshot();
		CUI_EXPECT_TRUE(programmaticAfterEnd.IsComposing);
		CUI_EXPECT_EQ(programmatic.CompositionId,
			programmaticAfterEnd.CompositionId);
		CUI_EXPECT_EQ(TextCompositionInputKind::Programmatic,
			programmaticAfterEnd.InputKind);
		CUI_EXPECT_EQ(1ULL,
			manager.Statistics().StaleImeEndsDiscarded);
		CUI_EXPECT_TRUE(manager.CompleteComposition(L"P"));
		CUI_EXPECT_EQ(std::wstring(L"xP"), second->Text);
		CUI_EXPECT_TRUE(manager.CompleteComposition(L"S"));
		CUI_EXPECT_EQ(std::wstring(L"xPS"), second->Text);

		const auto nextNativeStart = manager.ProcessWindowMessage(
			WM_IME_STARTCOMPOSITION, 0, 0);
		CUI_EXPECT_TRUE(nextNativeStart.Recognized);
		const auto restarted = manager.Snapshot();
		CUI_EXPECT_TRUE(restarted.IsComposing);
		CUI_EXPECT_TRUE(restarted.Source == second);
		CUI_EXPECT_EQ(TextCompositionInputKind::Ime, restarted.InputKind);
		bool freshUpdateSuppressed = true;
		CUI_EXPECT_FALSE(
			TextCompositionManagerTestAccess::ProcessNativeCompositionPayload(
				manager, false, {}, true, L"fresh-preedit",
				freshUpdateSuppressed, 5));
		CUI_EXPECT_FALSE(freshUpdateSuppressed);
		CUI_EXPECT_TRUE(manager.Snapshot().IsComposing);
		CUI_EXPECT_EQ(std::wstring(L"fresh-preedit"),
			manager.Snapshot().CompositionText);
		bool freshResultSuppressed = true;
		CUI_EXPECT_TRUE(
			TextCompositionManagerTestAccess::ProcessNativeCompositionPayload(
				manager, true, L"N", false, {},
				freshResultSuppressed));
		CUI_EXPECT_FALSE(freshResultSuppressed);
		CUI_EXPECT_EQ(std::wstring(L"xPSN"), second->Text);
		CUI_EXPECT_FALSE(manager.Snapshot().IsComposing);
		CUI_EXPECT_EQ(TextCompositionInputKind::Ime,
			manager.Snapshot().InputKind);
		(void)manager.ProcessWindowMessage(WM_IME_ENDCOMPOSITION, 0, 0);

		(void)manager.ProcessWindowMessage(WM_IME_STARTCOMPOSITION, 0, 0);
		CUI_EXPECT_TRUE(manager.UpdateComposition(L"language-reset", 4));
		manager.CancelComposition(TextCompositionCancelReason::Explicit);
		CUI_EXPECT_EQ(2ULL,
			manager.Statistics().NativeImeSessionsTombstoned);
		CUI_EXPECT_TRUE(manager.StartComposition(
			second, TextCompositionInputKind::Programmatic));
		CUI_EXPECT_TRUE(manager.UpdateComposition(
			L"survive-language-reset", 8));
		const auto beforeLanguageReset = manager.Snapshot();
		const auto languageReset = manager.ProcessWindowMessage(
			WM_INPUTLANGCHANGE, 0, 0);
		CUI_EXPECT_TRUE(languageReset.Recognized);
		const auto afterLanguageReset = manager.Snapshot();
		CUI_EXPECT_TRUE(afterLanguageReset.IsComposing);
		CUI_EXPECT_EQ(beforeLanguageReset.CompositionId,
			afterLanguageReset.CompositionId);
		CUI_EXPECT_EQ(TextCompositionInputKind::Programmatic,
			afterLanguageReset.InputKind);
		CUI_EXPECT_EQ(std::wstring(L"survive-language-reset"),
			afterLanguageReset.CompositionText);
		CUI_EXPECT_TRUE(manager.CompleteComposition(L"L"));
		bool afterLanguageResetSuppressed = true;
		CUI_EXPECT_FALSE(
			TextCompositionManagerTestAccess::ProcessNativeCompositionPayload(
				manager, false, {}, true, L"after-language-reset",
				afterLanguageResetSuppressed, 5));
		CUI_EXPECT_FALSE(afterLanguageResetSuppressed);
		CUI_EXPECT_TRUE(manager.Snapshot().IsComposing);
		CUI_EXPECT_TRUE(manager.Snapshot().Source == second);
		CUI_EXPECT_EQ(std::wstring(L"after-language-reset"),
			manager.Snapshot().CompositionText);
		bool resetResultSuppressed = true;
		CUI_EXPECT_TRUE(
			TextCompositionManagerTestAccess::ProcessNativeCompositionPayload(
				manager, true, L"R", false, {}, resetResultSuppressed));
		CUI_EXPECT_FALSE(resetResultSuppressed);
		CUI_EXPECT_FALSE(manager.Snapshot().IsComposing);
		manager.Reset();
		bool afterResetSuppressed = false;
		CUI_EXPECT_FALSE(
			TextCompositionManagerTestAccess::ProcessNativeCompositionPayload(
				manager, true, L"stale-after-reset", true,
				L"must-not-restart-after-reset", afterResetSuppressed, 4));
		CUI_EXPECT_TRUE(afterResetSuppressed);
		CUI_EXPECT_FALSE(manager.Snapshot().IsComposing);
		const auto finalStatistics = manager.Statistics();
		CUI_EXPECT_EQ(2ULL, finalStatistics.StaleImeResultsDiscarded);
		CUI_EXPECT_EQ(3ULL,
			finalStatistics.StaleImeCompositionUpdatesDiscarded);
		CUI_EXPECT_EQ(1ULL, finalStatistics.StaleImeEndsDiscarded);
		CUI_EXPECT_EQ(3ULL,
			finalStatistics.NativeImeSessionsTombstoned);
	});

	runner.Add("TextCompositionManager guards caret placement reentry and ignores placement feedback", []
	{
		class ReentrantCaretTextBox final : public TextBox
		{
		public:
			using TextBox::TextBox;
			TextCompositionManager* Manager = nullptr;
			int CaretQueries = 0;
			bool NestedResult = true;

			bool TryGetTextInputCaretRect(D2D1_RECT_F& outRect) override
			{
				++CaretQueries;
				if (CaretQueries == 1 && Manager)
					NestedResult = Manager->UpdateCaretPosition();
				outRect = D2D1_RECT_F{ 4.0f, 5.0f, 5.0f, 21.0f };
				return true;
			}
		};

		Window form; ConfigureTestControl(form, L"IME caret guard");
		SetDeclaredWindowGeometry(form, 0.0f, 0.0f, 360.0f, 180.0f);
		auto contentOwner = MakeTestControl<Panel>();
		auto* content = static_cast<Panel*>(
			form.SetVisualContent(std::move(contentOwner)));
		auto* editor = AddTestVisual<ReentrantCaretTextBox>(*content,
			L"", 0, 0, 220, 28);
		editor->Focusable = true;
		form.SetKeyboardFocus(editor, false);

		auto& manager = cui::framework::WindowAccess::TextComposition(form);
		editor->Manager = &manager;
		CUI_EXPECT_TRUE(manager.StartComposition(
			editor, TextCompositionInputKind::Ime));
		CUI_EXPECT_EQ(1, editor->CaretQueries);
		CUI_EXPECT_FALSE(editor->NestedResult);
		const auto afterStart = manager.Statistics();
		CUI_EXPECT_EQ(1ULL, afterStart.CaretPlacementRequests);
		CUI_EXPECT_TRUE(
			afterStart.CaretPlacementReentriesSuppressed >= 1ULL);

		const auto compositionFeedback = manager.ProcessWindowMessage(
			WM_IME_NOTIFY, IMN_SETCOMPOSITIONWINDOW, 0);
		const auto candidateFeedback = manager.ProcessWindowMessage(
			WM_IME_NOTIFY, IMN_SETCANDIDATEPOS, 0);
		CUI_EXPECT_TRUE(compositionFeedback.Recognized);
		CUI_EXPECT_TRUE(candidateFeedback.Recognized);
		const auto afterFeedback = manager.Statistics();
		CUI_EXPECT_EQ(afterStart.CaretPlacementRequests,
			afterFeedback.CaretPlacementRequests);
		CUI_EXPECT_EQ(afterStart.CaretPlacementReentriesSuppressed,
			afterFeedback.CaretPlacementReentriesSuppressed);
		CUI_EXPECT_EQ(afterStart.CaretNotificationsIgnored + 2,
			afterFeedback.CaretNotificationsIgnored);
		CUI_EXPECT_EQ(afterStart.NativeReports + 2,
			afterFeedback.NativeReports);

		const auto openCandidate = manager.ProcessWindowMessage(
			WM_IME_NOTIFY, IMN_OPENCANDIDATE, 0);
		CUI_EXPECT_TRUE(openCandidate.Recognized);
		const auto afterOpen = manager.Statistics();
		CUI_EXPECT_EQ(afterFeedback.CaretPlacementRequests + 1,
			afterOpen.CaretPlacementRequests);
		CUI_EXPECT_EQ(2, editor->CaretQueries);
	});

