		column->SetBindingPath(L"Name");
		column->SetWidth(DataGridLength(220.0));
		CUI_EXPECT_TRUE(grid->AddColumn(std::move(column)) != nullptr);

		auto rows = std::make_shared<ObservableBindingList>(
			L"GroupedRowResizeRow");
